script.code:
/**
 * Header Cards Handler
 * V21 - Slim Tank Monitoring + Connectivity Trend
 */

if (typeof HeaderCards === 'undefined') {
    var HeaderCards = {};
}

HeaderCards.init = function (host) {
    var U = HeaderGlobals.UTILS;
    var doc = host.ownerDocument || document;
    var base = HeaderGlobals.CONFIG.BASE || "";
    HeaderCards.equipmentLiveStates = {};
    HeaderCards.chartBadges = {};
    U.log("--- HeaderCards.init (V21) START ---");

    try {
        // --- Theme (V21 Refined) ---
        var theme = U.getTheme(base);

        // --- Card 1: Slim Tank Monitoring (Rectangular V21) ---
        var tankCard = U.x(doc, 'div');
        tankCard.style.position = "absolute";
        tankCard.style.left = "425px"; tankCard.style.top = "16px";
        tankCard.style.width = "220px"; tankCard.style.height = "305px";
        tankCard.style.background = "#ffffff";
        tankCard.style.border = "1px solid #e2e8f0";
        tankCard.style.borderRadius = "12px";
        tankCard.style.boxShadow = "0 4px 6px -1px rgba(0, 0, 0, 0.05), 0 2px 4px -1px rgba(0, 0, 0, 0.03)";
        tankCard.style.padding = "10px";
        tankCard.style.boxSizing = "border-box";
        tankCard.style.fontFamily = "Arial, sans-serif";
        tankCard.style.display = "flex";
        tankCard.style.flexDirection = "column";
        tankCard.style.gap = "8px";
        tankCard.style.cursor = "pointer";
        tankCard.style.transition = "all 0.2s ease-in-out";

        tankCard.onmouseenter = function () {
            this.style.boxShadow = "0 12px 20px -5px rgba(0, 0, 0, 0.15), 0 8px 10px -6px rgba(0, 0, 0, 0.1)";
            this.style.borderColor = theme.col;
            this.style.background = "#f8fafc";
        };
        tankCard.onmouseleave = function () {
            this.style.boxShadow = "0 4px 6px -1px rgba(0, 0, 0, 0.05), 0 2px 4px -1px rgba(0, 0, 0, 0.03)";
            this.style.borderColor = "#e2e8f0";
            this.style.background = "#ffffff";
        };
        tankCard.onclick = function () {
            HeaderCards.showTankFullscreen(base, doc);
        };

        var headerRow = U.x(doc, 'div');
        headerRow.style.display = "flex";
        headerRow.style.justifyContent = "space-between";
        headerRow.style.alignItems = "center";

        var isResidual = base.toLowerCase().indexOf("residual") >= 0 || base.toLowerCase().indexOf("cuencas") >= 0;
        var tankLabelText = isResidual ? "Nivel del Cárcamo" : "Nivel del Tanque";

        var lblT = U.x(doc, 'div'); lblT.style.fontWeight = "bold"; lblT.style.color = theme.col; lblT.style.fontSize = "13px";
        lblT.textContent = tankLabelText;
        headerRow.appendChild(lblT);

        var pct = U.x(doc, 'div');
        pct.id = "tk_pct"; pct.style.fontSize = "16px"; pct.style.fontWeight = "bold";
        pct.style.color = theme.col; pct.textContent = "--%";
        headerRow.appendChild(pct);

        tankCard.appendChild(headerRow);

        // Vertical Bar Indicator (Legacy Style: Integrated Box)
        var vBarBox = U.x(doc, 'div');
        vBarBox.style.height = "165px"; vBarBox.style.background = "#f1f5f9"; vBarBox.style.borderRadius = "8px";
        vBarBox.style.border = "1px solid #e2e8f0"; vBarBox.style.position = "relative"; vBarBox.style.overflow = "hidden";

        var fill = U.x(doc, 'div');
        fill.id = "tk_fill"; fill.style.position = "absolute"; fill.style.bottom = "0"; fill.style.left = "0"; fill.style.width = "100%";
        fill.style.background = theme.bg; fill.style.height = "0%";
        fill.style.transition = "height 0.5s ease";
        fill.style.zIndex = "1"; // Water level at bottom
        vBarBox.appendChild(fill);

        // Sparkline Container (Now inside vBarBox)
        var sparkBox = U.x(doc, 'div');
        sparkBox.id = "tk_spark_box";
        sparkBox.style.position = "absolute";
        sparkBox.style.top = "0"; sparkBox.style.left = "0";
        sparkBox.style.width = "100%"; sparkBox.style.height = "100%";
        sparkBox.style.zIndex = "5"; // Graph above water
        vBarBox.appendChild(sparkBox);

        tankCard.appendChild(vBarBox);

        // Statistics Panel (NEW)
        var statsBox = U.x(doc, 'div');
        statsBox.style.display = "grid";
        statsBox.style.gridTemplateColumns = "1fr 1fr";
        statsBox.style.gap = "6px";
        statsBox.style.fontSize = "11px";

        function createStat(label, id, span, vSize) {
            var s = U.x(doc, 'div');
            s.style.background = "#f8fafc";
            s.style.padding = "4px 6px";
            s.style.borderRadius = "6px";
            s.style.border = "1px solid #e2e8f0";
            if (span) s.style.gridColumn = "span " + span;
            s.innerHTML = "<div style='color:#64748b;font-size:9px;font-weight:bold;text-transform:uppercase;margin-bottom:2px'>" + label + "</div>" +
                "<div id='" + id + "' style='font-size:" + (vSize || "11px") + ";font-weight:bold;color:" + theme.col + ";white-space:nowrap'>--</div>";
            return s;
        }

        statsBox.appendChild(createStat("Promedio", "tk_stat_avg", 1));
        statsBox.appendChild(createStat("Cloro (ppm)", "tk_stat_ppm", 1));
        statsBox.appendChild(createStat("Máximo", "tk_stat_max", 1, "9.5px"));
        statsBox.appendChild(createStat("Mínimo", "tk_stat_min", 1, "9.5px"));

        tankCard.appendChild(statsBox);

        host.appendChild(tankCard);

        // --- Card 2: Installation Info (3-Section Layout) ---
        var trendCard = U.x(doc, 'div');
        trendCard.style.position = "absolute";
        trendCard.style.left = "648px"; trendCard.style.top = "16px";
        trendCard.style.width = "615px"; trendCard.style.height = "305px";
        trendCard.style.background = "#ffffff";
        trendCard.style.border = "1px solid #e2e8f0";
        trendCard.style.borderRadius = "12px";
        trendCard.style.boxShadow = "0 4px 6px -1px rgba(0, 0, 0, 0.05), 0 2px 4px -1px rgba(0, 0, 0, 0.03)";
        trendCard.style.padding = "10px";
        trendCard.style.boxSizing = "border-box";
        trendCard.style.fontFamily = "Arial, sans-serif";
        trendCard.style.display = "flex";
        trendCard.style.flexDirection = "column";

        var iHead = U.x(doc, 'div'); iHead.style.cssText = "display:flex; justify-content:space-between; align-items:flex-start; margin-bottom:12px;";
        var iTitle = U.x(doc, 'div'); iTitle.style.cssText = "font-weight:900; color:#1e3a8a; font-size:18px; letter-spacing:-0.02em;"; iTitle.textContent = "Información de la Instalación";
        var iName = U.x(doc, 'div'); iName.id = "info_name_top"; iName.style.cssText = "font-weight:bold; color:#3b82f6; font-size:16px; text-transform:uppercase; background:#eff6ff; padding:4px 12px; border-radius:8px; border:1px solid #dbeafe;"; iName.textContent = "--";
        iHead.appendChild(iTitle); iHead.appendChild(iName); trendCard.appendChild(iHead);

        var grid = U.x(doc, 'div');
        grid.style.display = "grid";
        grid.style.gridTemplateColumns = "1.2fr 1fr";
        grid.style.gap = "10px";
        grid.style.flex = "1";
        trendCard.appendChild(grid);

        // Section 1: General Info
        var secInfo = U.x(doc, 'div');
        secInfo.style.display = "flex"; secInfo.style.flexDirection = "column"; secInfo.style.gap = "6px";
        secInfo.style.fontSize = "13px"; secInfo.style.color = "#475569";

        function addInfoLine(label, id) {
            var row = U.x(doc, 'div');
            row.style.whiteSpace = "nowrap"; row.style.overflow = "hidden"; row.style.textOverflow = "ellipsis";
            row.innerHTML = "<span style='font-weight:bold;color:#1e40af'>" + label + ":</span> <span id='" + id + "'>--</span>";
            secInfo.appendChild(row);
        }
        // Removed: addInfoLine("Nombre", "info_name");
        addInfoLine("Código SAP", "info_sap");
        addInfoLine("IP Address", "info_ip");
        addInfoLine("Gateway", "info_gtw");
        addInfoLine("Responsable", "info_resp");
        addInfoLine("Teléfono", "info_tel");
        grid.appendChild(secInfo);

        // Section 2: Connectivity (1H)
        var secConn = U.x(doc, 'div');
        secConn.style.display = "flex"; secConn.style.flexDirection = "column";
        var subT = U.x(doc, 'div');
        subT.textContent = "CONECTIVIDAD (12H)"; subT.style.fontSize = "9px"; subT.style.fontWeight = "bold"; subT.style.marginBottom = "2px";
        secConn.appendChild(subT);

        var graphWrap = U.x(doc, 'div');
        graphWrap.style.height = "100px"; graphWrap.style.background = "#f8fafc"; graphWrap.style.borderRadius = "6px";
        graphWrap.style.border = "1px solid #e2e8f0"; graphWrap.style.position = "relative";
        graphWrap.style.marginTop = "4px";

        var svg = U.x(doc, "svg");
        svg.style.width = "100%"; svg.style.height = "100%";
        graphWrap.appendChild(svg);

        var tooltip = U.x(doc, 'div');
        tooltip.id = "conn_tooltip";
        tooltip.style.position = "absolute"; tooltip.style.display = "none";
        tooltip.style.background = "rgba(0, 0, 0, 0.9)"; tooltip.style.color = "#ffffff";
        tooltip.style.padding = "6px 10px"; tooltip.style.borderRadius = "6px";
        tooltip.style.fontSize = "12px"; tooltip.style.fontWeight = "500"; tooltip.style.pointerEvents = "none";
        tooltip.style.zIndex = "100"; tooltip.style.boxShadow = "0 4px 12px rgba(0,0,0,0.5)";
        tooltip.style.border = "1px solid rgba(255,255,255,0.1)";
        graphWrap.appendChild(tooltip);
        secConn.appendChild(graphWrap);
        grid.appendChild(secConn);

        // Section 3: Energy Table (Span 2)
        var secEnergy = U.x(doc, 'div');
        secEnergy.id = "secEnergy";
        secEnergy.style.gridColumn = "span 2";
        secEnergy.style.marginTop = "-5px";
        secEnergy.style.background = "#f8fafc";
        secEnergy.style.borderRadius = "8px";
        secEnergy.style.padding = "8px";
        secEnergy.style.border = "1px solid #e2e8f0";
        secEnergy.style.display = "flex";
        secEnergy.style.flexDirection = "column";

        // Container for Tabs + Fullscreen Button
        var energyHeader = U.x(doc, "div");
        energyHeader.style.display = "flex";
        energyHeader.style.justifyContent = "space-between";
        energyHeader.style.alignItems = "center";
        energyHeader.style.marginBottom = "4px";

        var pacTabsDiv = U.x(doc, "div");
        pacTabsDiv.id = "energy_pac_tabs";
        pacTabsDiv.style.display = "flex";
        pacTabsDiv.style.gap = "8px";
        energyHeader.appendChild(pacTabsDiv);

        var btnFs = U.x(doc, "button");
        btnFs.id = "energy_fs_btn";
        btnFs.textContent = "Pantalla completa";
        btnFs.style.display = "none"; // Hidden by default, shown if PACs found
        btnFs.style.padding = "4px 10px";
        btnFs.style.border = "1px solid #cbd5e1";
        btnFs.style.borderRadius = "6px";
        btnFs.style.background = "#fff";
        btnFs.style.fontSize = "11px";
        btnFs.style.fontWeight = "600";
        btnFs.style.cursor = "pointer";
        btnFs.style.transition = "all 0.2s ease";
        btnFs.onmouseenter = function () { this.style.background = "#eff6ff"; this.style.borderColor = "#3b82f6"; };
        btnFs.onmouseleave = function () { this.style.background = "#fff"; this.style.borderColor = "#cbd5e1"; };
        energyHeader.appendChild(btnFs);

        secEnergy.appendChild(energyHeader);

        // Energy Table
        var energyTableDiv = U.x(doc, 'div');
        energyTableDiv.innerHTML = "<table style='width:100%; border-collapse:collapse; font-size:12px; color:#334155; table-layout: fixed;'>" +
            "<tr style='background:#f1f5f9; color:#64748b;'><th style='padding:6px; text-align:left; border-radius:6px 0 0 6px; width:120px;'>Parámetro</th><th>L1-L2</th><th>L2-L3</th><th>L3-L1</th><th style='border-radius:0 6px 6px 0;'>Prom.</th></tr>" +
            "<tr style='border-bottom:1px solid #f1f5f9'><td style='padding:8px 6px; font-weight:bold;'>Voltaje (V)</td><td id='e_v12' style='text-align:center'>--</td><td id='e_v23' style='text-align:center'>--</td><td id='e_v31' style='text-align:center'>--</td><td id='e_vavg' style='text-align:center'>--</td></tr>" +
            "<tr><td style='padding:8px 6px; font-weight:bold;'>Corriente (A)</td><td id='e_i1' style='text-align:center'>--</td><td id='e_i2' style='text-align:center'>--</td><td id='e_i3' style='text-align:center'>--</td><td id='e_iavg' style='text-align:center'>--</td></tr>" +
            "</table>";
        secEnergy.appendChild(energyTableDiv);
        grid.appendChild(secEnergy);

        host.appendChild(trendCard);

        // --- Data Wiring ---
        HeaderCards.wireTank(base, sparkBox, doc);
        HeaderCards.wireInfoCard(base, svg, tooltip, doc);

    } catch (e) {
        U.log("Error in V21 Init:", e);
    }
};

HeaderCards.wireTank = function (base, sparkContainer, doc) {
    var U = HeaderGlobals.UTILS;
    var d = doc || document;
    if (!base) return;
    U.log("HeaderCards.wireTank (V3) - START: " + base);
    var theme = U.getTheme(base);

    // Track presence of Chlorine
    var hasChlorine = true;

    function wireNode(node, cb) {
        webMI.data.read(node, function (e) { cb(e); });
        webMI.data.subscribe(node, function (e) { cb(e); });
    }

    // 1. Real-Time Status
    wireNode(base + ".level_percent", function (res) {
        var v = (res && res.value != null) ? parseFloat(res.value) : 0;
        var elFill = d.getElementById("tk_fill");
        var elPct = d.getElementById("tk_pct");
        if (elFill) elFill.style.height = Math.min(100, Math.max(0, v)) + "%";
        if (elPct) elPct.textContent = v.toFixed(1) + "%";
    });

    wireNode(base + ".ppm", function (res) {
        var el = d.getElementById("tk_stat_ppm");
        if (!el) return;
        if (!hasChlorine) {
            el.textContent = "N/A";
            return;
        }
        el.textContent = (res && res.value != null ? parseFloat(res.value).toFixed(2) : "0.00") + " ppm";
    });

    // 2. History for Dual Sparkline (12h)
    if (sparkContainer) {
        function fmtT(ts) {
            var dt = new Date(ts);
            var h = dt.getHours(), m = dt.getMinutes();
            var ampm = h >= 12 ? 'PM' : 'AM';
            h = h % 12; h = h || 12;
            return h + ":" + (m < 10 ? "0" + m : m) + " " + ampm;
        }

        function loadHistory() {
            var now = Date.now();
            var from = now - 12 * 60 * 60 * 1000;
            var lAddr = "g:" + base + ".historic_level_percent";
            var cAddr = "g:" + base + ".historic_ppm";

            var seriesL = [], seriesC = [];
            var pending = 2;

            function onQueryDone() {
                pending--;
                if (pending > 0) return;

                // Level Stats
                if (seriesL.length > 0) {
                    var sum = 0, max = -Infinity, min = Infinity, maxT = 0, minT = 0;
                    seriesL.forEach(function (p) {
                        sum += p.v;
                        if (p.v >= max) { max = p.v; maxT = p.t; }
                        if (p.v <= min) { min = p.v; minT = p.t; }
                    });
                    var avg = sum / seriesL.length;
                    var elAvg = d.getElementById("tk_stat_avg");
                    var elMax = d.getElementById("tk_stat_max");
                    var elMin = d.getElementById("tk_stat_min");
                    if (elAvg) elAvg.textContent = avg.toFixed(1) + "%";
                    if (elMax) elMax.textContent = max.toFixed(1) + "% (" + fmtT(maxT) + ")";
                    if (elMin) elMin.textContent = min.toFixed(1) + "% (" + fmtT(minT) + ")";
                }

                // Chlorine Logic: Use historical average to decide if present
                var cSum = 0;
                seriesC.forEach(function (p) { cSum += p.v; });
                var cAvg = seriesC.length > 0 ? cSum / seriesC.length : 0;

                // If avg is 0 or no points, it's N/A
                hasChlorine = (seriesC.length > 0 && cAvg > 0);

                var elPpm = d.getElementById("tk_stat_ppm");
                if (elPpm && !hasChlorine) {
                    elPpm.textContent = "N/A";
                }

                sparkContainer.innerHTML = "";
                // If no chlorine, pass empty seriesC to suppress orange line
                var drawC = hasChlorine ? seriesC : [];
                HeaderCards.buildDualSpark(d, sparkContainer, seriesL, theme.col, drawC, "#f97316");
                U.log("HeaderCards.loadHistory - Dual Sparklines updated. Chlorine Presence: " + hasChlorine);
            }

            try {
                U.readHist(base + ".historic_level_percent", from, now, function (raw) {
                    seriesL = U.group5Minutes(raw);
                    onQueryDone();
                });

                U.readHist(base + ".historic_ppm", from, now, function (raw) {
                    seriesC = U.group5Minutes(raw);
                    onQueryDone();
                });
            } catch (e) {
                U.log("HeaderCards.loadHistory ERROR: " + e.message);
                pending = 0;
            }
        }

        loadHistory();
        if (sparkContainer._refreshTimer) clearInterval(sparkContainer._refreshTimer);
        sparkContainer._refreshTimer = setInterval(loadHistory, 5 * 60 * 1000);
    }
};

// Utility functions moved to HeaderGlobals.UTILS

HeaderCards.buildSpark = function (doc, container, series, color, unit, minVal, maxVal) {
    var U = HeaderGlobals.UTILS;
    if (!container) return;
    var w = container.clientWidth || 200;
    var h = container.clientHeight || 80;
    var pad = 5;

    var svg = U.x(doc, "svg");
    svg.setAttribute("width", w); svg.setAttribute("height", h);
    svg.style.display = "block";
    container.appendChild(svg);

    if (!series || series.length < 2) {
        var txt = U.x(doc, "text");
        txt.textContent = "Sin datos";
        txt.setAttribute("x", w / 2); txt.setAttribute("y", h / 2);
        txt.setAttribute("text-anchor", "middle"); txt.setAttribute("fill", "#94a3b8");
        txt.setAttribute("font-size", "10");
        svg.appendChild(txt);
        return;
    }

    var ys = series.map(function (d) { return d.v; });
    var min = (minVal !== undefined) ? minVal : Math.min.apply(null, ys);
    var max = (maxVal !== undefined) ? maxVal : Math.max.apply(null, ys);
    if (min === max) { min -= 1; max += 1; }
    var range = max - min;

    // Scale functions
    function sx(i) { return pad + (i / (series.length - 1)) * (w - 2 * pad); }
    function sy(v) { return h - pad - ((v - min) / range) * (h - 2 * pad); }

    var dLine = "M" + sx(0) + "," + sy(series[0].v);
    var dArea = dLine;
    for (var i = 1; i < series.length; i++) {
        var p = sx(i) + "," + sy(series[i].v);
        dLine += " L" + p;
        dArea += " L" + p;
    }
    dArea += " L" + sx(series.length - 1) + "," + (h - pad) + " L" + sx(0) + "," + (h - pad) + " Z";

    var pathArea = U.x(doc, "path");
    pathArea.setAttribute("d", dArea);
    pathArea.setAttribute("fill", color);
    pathArea.setAttribute("opacity", "0.15");
    pathArea.setAttribute("stroke", "none");
    svg.appendChild(pathArea);

    var pathLine = U.x(doc, "path");
    pathLine.setAttribute("d", dLine);
    pathLine.setAttribute("fill", "none");
    pathLine.setAttribute("stroke", color);
    pathLine.setAttribute("stroke-width", "2");
    pathLine.setAttribute("stroke-linejoin", "round");
    svg.appendChild(pathLine);

    // Tooltip elements (with background)
    var tipBg = U.x(doc, "rect");
    tipBg.setAttribute("rx", "6"); tipBg.setAttribute("ry", "6");
    tipBg.setAttribute("fill", "rgba(15, 23, 42, 0.95)");
    tipBg.setAttribute("stroke", "rgba(255,255,255,0.1)");
    tipBg.setAttribute("stroke-width", "1");
    tipBg.style.display = "none";
    tipBg.style.filter = "drop-shadow(0 4px 12px rgba(0,0,0,0.5))";
    svg.appendChild(tipBg);

    var dot = U.x(doc, "circle");
    dot.setAttribute("r", "3"); dot.setAttribute("fill", "#fff"); dot.setAttribute("stroke", color); dot.setAttribute("stroke-width", "2");
    dot.style.display = "none";
    svg.appendChild(dot);

    var tip = U.x(doc, "text");
    tip.setAttribute("font-size", "18"); tip.setAttribute("fill", "#ffffff"); tip.setAttribute("font-weight", "500");
    tip.style.display = "none";
    svg.appendChild(tip);

    // Interaction
    svg.onmousemove = function (e) {
        var rect = svg.getBoundingClientRect();
        var mx = e.clientX - rect.left;
        var ratio = Math.max(0, Math.min(1, (mx - pad) / (rect.width - 2 * pad)));
        var idx = Math.round(ratio * (series.length - 1));
        var p = series[idx];

        var d = new Date(p.t);
        var dateStr = d.toLocaleDateString([], { day: '2-digit', month: '2-digit' });
        var timeStr = d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: true });

        dot.style.display = "block";
        dot.setAttribute("r", "5");
        dot.setAttribute("cx", sx(idx)); dot.setAttribute("cy", sy(p.v));

        tip.textContent = p.v.toFixed(1) + (unit || "") + " | " + dateStr + " " + timeStr;
        var tx = sx(idx) < rect.width / 2 ? sx(idx) + 12 : sx(idx) - 12;
        tip.setAttribute("x", tx); tip.setAttribute("y", sy(p.v) - 15);
        tip.setAttribute("text-anchor", sx(idx) < rect.width / 2 ? "start" : "end");
        tip.style.display = "block";

        try {
            var bbox = tip.getBBox();
            var bgPad = 8;
            tipBg.setAttribute("x", bbox.x - bgPad); tipBg.setAttribute("y", bbox.y - bgPad);
            tipBg.setAttribute("width", bbox.width + 2 * bgPad); tipBg.setAttribute("height", bbox.height + 2 * bgPad);
            tipBg.style.display = "block";
        } catch (e) { }
    };
    svg.onmouseleave = function () {
        dot.style.display = "none"; tip.style.display = "none"; tipBg.style.display = "none";
    };
};

HeaderCards.buildDualSpark = function (doc, container, seriesL, colorL, seriesC, colorC) {
    var U = HeaderGlobals.UTILS;
    if (!container) return;
    var w = container.clientWidth || 200;
    var h = container.clientHeight || 150;
    var pad = 5;

    var svg = U.x(doc, "svg");
    svg.setAttribute("width", w); svg.setAttribute("height", h);
    svg.style.display = "block";
    container.appendChild(svg);

    if (seriesL.length < 2 && seriesC.length < 2) {
        var txt = U.x(doc, "text");
        txt.textContent = "Sin datos históricos";
        txt.setAttribute("x", w / 2); txt.setAttribute("y", h / 2);
        txt.setAttribute("text-anchor", "middle"); txt.setAttribute("fill", "#94a3b8");
        txt.setAttribute("font-size", "10");
        svg.appendChild(txt);
        return;
    }

    // Scaling Level (0-100)
    function sx(i, len) { return pad + (i / (len - 1)) * (w - 2 * pad); }
    function syL(v) { return h - pad - (Math.min(100, Math.max(0, v)) / 100) * (h - 2 * pad); }

    // Scaling Chlorine (Auto or fixed? Let's use auto for Chlorine to see detail)
    var valsC = seriesC.map(function (d) { return d.v; });
    var minC = seriesC.length > 0 ? Math.min.apply(null, valsC) : 0;
    var maxC = seriesC.length > 0 ? Math.max.apply(null, valsC) : 2;
    if (minC === maxC) { minC -= 0.1; maxC += 0.1; }
    var rangeC = maxC - minC;
    function syC(v) { return h - pad - ((v - minC) / rangeC) * (h - 2 * pad); }

    function drawPath(series, scaleY, color, opacity) {
        if (series.length < 2) return;
        var dLine = "M" + sx(0, series.length) + "," + scaleY(series[0].v);
        var dArea = dLine;
        for (var i = 1; i < series.length; i++) {
            var p = sx(i, series.length) + "," + scaleY(series[i].v);
            dLine += " L " + p;
            dArea += " L " + p;
        }
        dArea += " L " + sx(series.length - 1, series.length) + "," + (h - pad) + " L " + sx(0, series.length) + "," + (h - pad) + " Z";

        var pathArea = U.x(doc, "path");
        pathArea.setAttribute("d", dArea); pathArea.setAttribute("fill", color);
        pathArea.setAttribute("opacity", opacity || "0.1"); pathArea.setAttribute("stroke", "none");
        svg.appendChild(pathArea);

        var pathLine = U.x(doc, "path");
        pathLine.setAttribute("d", dLine); pathLine.setAttribute("fill", "none");
        pathLine.setAttribute("stroke", color); pathLine.setAttribute("stroke-width", "1.5");
        pathLine.setAttribute("stroke-linejoin", "round");
        svg.appendChild(pathLine);
    }

    // Draw Level
    drawPath(seriesL, syL, colorL, 0.15);
    // Draw Chlorine
    drawPath(seriesC, syC, colorC, 0.1);

    // Shared Interaction (Dual Tooltip)
    var tipBg = U.x(doc, "rect");
    tipBg.setAttribute("rx", "6"); tipBg.setAttribute("ry", "6");
    tipBg.setAttribute("fill", "rgba(15, 23, 42, 0.95)"); tipBg.setAttribute("stroke", "rgba(255,255,255,0.1)");
    tipBg.setAttribute("stroke-width", "1"); tipBg.style.display = "none";
    tipBg.style.filter = "drop-shadow(0 4px 12px rgba(0,0,0,0.5))";
    svg.appendChild(tipBg);

    var tip = U.x(doc, "text");
    tip.setAttribute("font-size", "18"); tip.setAttribute("fill", "#ffffff"); tip.style.display = "none";
    svg.appendChild(tip);

    var dotL = U.x(doc, "circle"); dotL.setAttribute("r", "4"); dotL.setAttribute("fill", "#fff");
    dotL.setAttribute("stroke", colorL); dotL.setAttribute("stroke-width", "2"); dotL.style.display = "none";
    svg.appendChild(dotL);

    var dotC = U.x(doc, "circle"); dotC.setAttribute("r", "4"); dotC.setAttribute("fill", "#fff");
    dotC.setAttribute("stroke", colorC); dotC.setAttribute("stroke-width", "2"); dotC.style.display = "none";
    svg.appendChild(dotC);

    svg.onmousemove = function (e) {
        var rect = svg.getBoundingClientRect();
        var mx = e.clientX - rect.left;
        var ratio = Math.max(0, Math.min(1, (mx - pad) / (rect.width - 2 * pad)));

        var idxL = Math.round(ratio * (seriesL.length - 1));
        var idxC = Math.round(ratio * (seriesC.length - 1));

        var pL = seriesL[idxL]; var pC = seriesC[idxC];
        if (!pL && !pC) return;

        var activeP = pL || pC;
        var timeStr = new Date(activeP.t).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

        // Update dot positions
        if (pL) {
            dotL.style.display = "block";
            dotL.setAttribute("cx", sx(idxL, seriesL.length));
            dotL.setAttribute("cy", syL(pL.v));
        } else {
            dotL.style.display = "none";
        }

        if (pC) {
            dotC.style.display = "block";
            dotC.setAttribute("cx", sx(idxC, seriesC.length));
            dotC.setAttribute("cy", syC(pC.v));
        } else {
            dotC.style.display = "none";
        }

        // Build tooltip text with multiple lines (tspans)
        tip.innerHTML = "";
        var linesData = [];
        if (pL) linesData.push({ t: "Nivel: " + pL.v.toFixed(1) + "%", c: colorL, b: true });
        if (pC) linesData.push({ t: "Cloro: " + pC.v.toFixed(2) + " ppm", c: colorC, b: true });
        linesData.push({ t: timeStr, c: "#94a3b8", b: false, s: "14px" });

        for (var i = 0; i < linesData.length; i++) {
            var tspan = doc.createElementNS("http://www.w3.org/2000/svg", "tspan");
            tspan.setAttribute("x", "0");
            tspan.setAttribute("dy", i === 0 ? "0" : "1.25em");
            tspan.style.fill = linesData[i].c;
            tspan.style.fontWeight = linesData[i].b ? "bold" : "normal";
            if (linesData[i].s) tspan.style.fontSize = linesData[i].s;
            tspan.textContent = linesData[i].t;
            tip.appendChild(tspan);
        }

        tip.style.display = "block";

        // Get text dimensions
        var bb = tip.getBBox();
        var paddingX = 16;
        var paddingY = 14;

        // Calculate tooltip position (centered at cursor)
        var tooltipWidth = bb.width + paddingX * 2;
        var tooltipHeight = bb.height + paddingY * 2;

        var lx = Math.min(
            Math.max(mx - tooltipWidth / 2, pad),
            rect.width - tooltipWidth - pad
        );

        // Fixed Y near top
        var ly = 32 + paddingY;

        // Position background
        tipBg.setAttribute("x", lx);
        tipBg.setAttribute("y", ly - 20); // Adjust for multi-line height
        tipBg.setAttribute("width", tooltipWidth);
        tipBg.setAttribute("height", tooltipHeight);
        tipBg.style.display = "block";

        // Position text
        tip.setAttribute("x", lx + paddingX);
        tip.setAttribute("y", ly);

        // Ensure all tspans use the same X offset
        var tspans = tip.getElementsByTagName("tspan");
        for (var j = 0; j < tspans.length; j++) {
            tspans[j].setAttribute("x", lx + paddingX);
        }
    };
    svg.onmouseleave = function () {
        dotL.style.display = "none"; dotC.style.display = "none";
        tip.style.display = "none"; tipBg.style.display = "none";
    };
};

HeaderCards.wireInfoCard = function (base, svg, tooltip, doc) {
    var U = HeaderGlobals.UTILS;
    var d = doc || document;
    var trendData = [];
    var W = svg.clientWidth || 250;
    var H = svg.clientHeight || 120;
    var pad = 6;

    function wireNode(node, cb) {
        webMI.data.read(node, function (e) { cb(e); });
        return webMI.data.subscribe(node, function (e) { cb(e); });
    }

    wireNode(base + ".short_name", function (r) {
        if (r && r.value != null) {
            var el = d.getElementById("info_name_top");
            if (el) {
                el.innerHTML = ""; // Clear
                var nameSpan = d.createElement("span");
                nameSpan.textContent = r.value;
                el.appendChild(nameSpan);

                // Add Status Badge Container
                var badge = d.createElement("span");
                badge.id = "conn_status_badge";
                badge.style.marginLeft = "12px";
                badge.style.fontSize = "12px";
                badge.style.padding = "2px 8px";
                badge.style.borderRadius = "20px";
                badge.style.display = "inline-flex";
                badge.style.alignItems = "center";
                badge.style.verticalAlign = "middle";
                badge.style.fontWeight = "900";
                el.appendChild(badge);
            }
        }
    });

    // Connectivity Badge Real-time Logic
    wireNode(base + ".connect", function (r) {
        var badge = d.getElementById("conn_status_badge");
        if (!badge) return;
        var isOnline = (r && (r.value === true || r.value === 1));
        if (isOnline) {
            badge.style.background = "#dcfce7";
            badge.style.color = "#166534";
            badge.style.border = "1px solid #86efac";
            badge.innerHTML = "<span style='margin-right:4px'>🟢</span> ONLINE";
        } else {
            badge.style.background = "#fee2e2";
            badge.style.color = "#991b1b";
            badge.style.border = "1px solid #f87171";
            badge.innerHTML = "<span style='margin-right:4px'>🔴</span> OFFLINE";
        }
    });
    wireNode(base + ".sap_name", function (r) { if (r && r.value != null) d.getElementById("info_sap").textContent = r.value; });
    wireNode(base + ".ip", function (r) { if (r && r.value != null) d.getElementById("info_ip").textContent = r.value; });
    wireNode(base + ".ip_gtw", function (r) { if (r && r.value != null) d.getElementById("info_gtw").textContent = r.value; });
    wireNode(base + ".Responsable", function (r) { if (r && r.value != null) d.getElementById("info_resp").textContent = r.value; });
    wireNode(base + ".Telefono_Responsable", function (r) { if (r && r.value != null) d.getElementById("info_tel").textContent = r.value; });

    // --- Dynamic PAC Energy Detection (reuses existing table IDs) ---
    var currentPACSubscriptions = []; // Track active subscriptions
    var currentPAC = null;

    function switchToPAC(pacAddr, pacName) {
        currentPACSubscriptions.forEach(function (sub) {
            if (sub && sub.unsubscribe) sub.unsubscribe();
            else if (typeof sub === "number") webMI.data.unsubscribe(sub);
        });
        currentPACSubscriptions = [];
        currentPAC = pacAddr;

        // Track individual values for client-side average calculation
        var pacVals = { v1: 0, v2: 0, v3: 0, i1: 0, i2: 0, i3: 0 };

        function updateTableAvgs() {
            var vAvg = (pacVals.v1 + pacVals.v2 + pacVals.v3) / 3;
            var iAvg = (pacVals.i1 + pacVals.i2 + pacVals.i3) / 3;
            var elV = d.getElementById("e_vavg");
            var elI = d.getElementById("e_iavg");
            if (elV) elV.textContent = vAvg.toFixed(1);
            if (elI) elI.textContent = iAvg.toFixed(1);
        }

        var nodes = [
            { n: ".Voltaje_L1-L2_Historico", id: "e_v12", vKey: "v1" },
            { n: ".Voltaje_L2-L3_Historico", id: "e_v23", vKey: "v2" },
            { n: ".Voltaje_L3-L1_Historico", id: "e_v31", vKey: "v3" },
            { n: ".Corriente_L1_Historico", id: "e_i1", vKey: "i1" },
            { n: ".Corriente_L2_Historico", id: "e_i2", vKey: "i2" },
            { n: ".Corriente_L3_Historico", id: "e_i3", vKey: "i3" }
        ];

        nodes.forEach(function (node) {
            var sub = wireNode(pacAddr + node.n, function (r) {
                if (r && r.value != null) {
                    var val = parseFloat(r.value);
                    var el = d.getElementById(node.id);
                    if (el) el.textContent = val.toFixed(1);

                    // Update tracking object and recalculate averages
                    if (node.vKey) {
                        pacVals[node.vKey] = val;
                        updateTableAvgs();
                    }
                }
            });
            currentPACSubscriptions.push(sub);
        });
    }

    var pacTabsDiv = d.getElementById("energy_pac_tabs");
    if (pacTabsDiv) {
        try {
            var pacPath = base + ".Equipos.Energia";
            webMI.data.call('ListarEquipos', {
                startAddress: pacPath, endLevel: '1', levelMode: 'exact',
                recursive: 'false', max: '0', includeStartAddress: 'false', debug: 'false'
            }, function (ret) {
                var pacs = [];
                if (ret && ret.items) {
                    pacs = ret.items.map(function (n) {
                        var a = String((n && n.address) || '');
                        var sid = a.indexOf('s='); if (sid >= 0) a = a.slice(sid + 2);
                        return { address: a, name: (n && n.name) || a.split(".").pop() };
                    }).filter(function (it) {
                        return it.address.indexOf(".meta") === -1 && it.address.indexOf(".db") === -1;
                    });
                }

                if (pacs.length === 0) {
                    wireNode(base + ".V12", function (r) { if (r && r.value != null) d.getElementById("e_v12").textContent = parseFloat(r.value).toFixed(1); });
                    wireNode(base + ".V23", function (r) { if (r && r.value != null) d.getElementById("e_v23").textContent = parseFloat(r.value).toFixed(1); });
                    wireNode(base + ".V31", function (r) { if (r && r.value != null) d.getElementById("e_v31").textContent = parseFloat(r.value).toFixed(1); });
                    wireNode(base + ".V_avg", function (r) { if (r && r.value != null) d.getElementById("e_vavg").textContent = parseFloat(r.value).toFixed(1); });
                    wireNode(base + ".I1", function (r) { if (r && r.value != null) d.getElementById("e_i1").textContent = parseFloat(r.value).toFixed(1); });
                    wireNode(base + ".I2", function (r) { if (r && r.value != null) d.getElementById("e_i2").textContent = parseFloat(r.value).toFixed(1); });
                    wireNode(base + ".I3", function (r) { if (r && r.value != null) d.getElementById("e_i3").textContent = parseFloat(r.value).toFixed(1); });
                    wireNode(base + ".I_avg", function (r) { if (r && r.value != null) d.getElementById("e_iavg").textContent = parseFloat(r.value).toFixed(1); });
                    return;
                }
                if (pacs.length > 0) { // Changed from `items.length` to `pacs.length`
                    pacTabsDiv.innerHTML = "";
                    var btnFs = d.getElementById("energy_fs_btn");
                    if (btnFs) {
                        btnFs.style.display = "block";
                        btnFs.onclick = function () { HeaderCards.showPACFullscreen(base, currentPAC, d, pacs); };
                    }
                    pacs.forEach(function (pac, idx) {
                        var tab = U.x(d, 'div');
                        tab.textContent = pac.name.replace(/_/g, " ") || ("PAC " + (idx + 1));
                        tab.style.fontSize = "11px";
                        tab.style.padding = "4px 12px";
                        tab.style.cursor = "pointer";
                        tab.style.borderRadius = "6px";
                        tab.style.fontWeight = "bold";
                        tab.style.transition = "all 0.2s";
                        tab.style.background = (idx === 0) ? "#3b82f6" : "#f1f5f9";
                        tab.style.color = (idx === 0) ? "#ffffff" : "#64748b";
                        tab.style.border = "1px solid " + ((idx === 0) ? "#2563eb" : "#e2e8f0");

                        tab.onclick = function () {
                            var allTabs = pacTabsDiv.children;
                            for (var i = 0; i < allTabs.length; i++) {
                                allTabs[i].style.background = "#f1f5f9";
                                allTabs[i].style.color = "#64748b";
                                allTabs[i].style.border = "1px solid #e2e8f0";
                            }
                            tab.style.background = "#3b82f6";
                            tab.style.color = "#ffffff";
                            tab.style.border = "1px solid #2563eb";
                            switchToPAC(pac.address, pac.name);
                        };

                        pacTabsDiv.appendChild(tab);
                        if (idx === 0) switchToPAC(pac.address, pac.name);
                    });

                    if (pacs.length <= 1) pacTabsDiv.style.display = "none";
                }
            });
        } catch (e) {
            wireNode(base + ".V12", function (r) { if (r && r.value != null) d.getElementById("e_v12").textContent = parseFloat(r.value).toFixed(1); });
            wireNode(base + ".V23", function (r) { if (r && r.value != null) d.getElementById("e_v23").textContent = parseFloat(r.value).toFixed(1); });
            wireNode(base + ".V31", function (r) { if (r && r.value != null) d.getElementById("e_v31").textContent = parseFloat(r.value).toFixed(1); });
            wireNode(base + ".V_avg", function (r) { if (r && r.value != null) d.getElementById("e_vavg").textContent = parseFloat(r.value).toFixed(1); });
            wireNode(base + ".I1", function (r) { if (r && r.value != null) d.getElementById("e_i1").textContent = parseFloat(r.value).toFixed(1); });
            wireNode(base + ".I2", function (r) { if (r && r.value != null) d.getElementById("e_i2").textContent = parseFloat(r.value).toFixed(1); });
            wireNode(base + ".I3", function (r) { if (r && r.value != null) d.getElementById("e_i3").textContent = parseFloat(r.value).toFixed(1); });
            wireNode(base + ".I_avg", function (r) { if (r && r.value != null) d.getElementById("e_iavg").textContent = parseFloat(r.value).toFixed(1); });
        }
    }

    function buildTrend(from, now) {
        while (svg.firstChild) svg.removeChild(svg.firstChild);

        var rect = svg.getBoundingClientRect();
        var CW = 300; // Fixed internal coordinate system
        var CH = 100;
        svg.setAttribute("viewBox", "0 0 " + CW + " " + CH);
        svg.style.width = "100%";
        svg.style.height = "100%";

        U.log("buildTrend: Drawing " + trendData.length + " points");

        if (trendData.length < 1) {
            var txt = U.x(d, "text");
            txt.textContent = "Sin datos";
            txt.setAttribute("x", CW / 2); txt.setAttribute("y", CH / 2);
            txt.setAttribute("dominant-baseline", "middle"); txt.setAttribute("text-anchor", "middle");
            txt.setAttribute("fill", "#94a3b8"); txt.setAttribute("font-size", "10");
            svg.appendChild(txt);
            return;
        }

        var timeSpan = now - from;
        function sx(t) { return pad + ((t - from) / timeSpan) * (CW - 2 * pad); }
        function sy(val) { return val ? 10 : (CH - 10); }

        var dPath = "";
        var dArea = "";
        if (trendData.length > 0) {
            dPath = "M " + sx(trendData[0].t) + " " + sy(trendData[0].v);
            for (var i = 1; i < trendData.length; i++) {
                var prev = trendData[i - 1];
                var curr = trendData[i];
                dPath += " L " + sx(curr.t) + " " + sy(prev.v);
                dPath += " L " + sx(curr.t) + " " + sy(curr.v);
            }
            dPath += " L " + sx(now) + " " + sy(trendData[trendData.length - 1].v);

            // Build Area Path
            dArea = dPath + " L " + sx(now) + " " + CH + " L " + sx(from) + " " + CH + " Z";
        }

        var area = U.x(d, 'path');
        area.setAttribute("d", dArea);
        area.setAttribute("fill", "#3b82f6");
        area.setAttribute("opacity", "0.1");
        svg.appendChild(area);

        var path = U.x(d, 'path');
        path.setAttribute("d", dPath);
        path.setAttribute("fill", "none");
        path.setAttribute("stroke", "#3b82f6");
        path.setAttribute("stroke-width", "2.5");
        path.setAttribute("stroke-linejoin", "round");
        svg.appendChild(path);

        var cursorLine = U.x(d, "line");
        cursorLine.setAttribute("y1", 0); cursorLine.setAttribute("y2", CH);
        cursorLine.setAttribute("stroke", "#64748b"); cursorLine.setAttribute("stroke-dasharray", "4,4");
        cursorLine.style.display = "none";
        svg.appendChild(cursorLine);

        svg.onmousemove = function (e) {
            var mRect = svg.getBoundingClientRect();
            var mx_screen = e.clientX - mRect.left;

            // Calculate ratio in screen space [0, 1]
            var ratio = Math.max(0, Math.min(1, (mx_screen - pad) / (mRect.width - 2 * pad)));
            var tHover = from + ratio * timeSpan;
            var px_svg = pad + ratio * (CW - 2 * pad);

            var state = null;
            var actualPointTime = null;
            for (var i = 0; i < trendData.length; i++) {
                if (trendData[i].t <= tHover) {
                    state = trendData[i].v;
                    actualPointTime = trendData[i].t;
                } else break;
            }

            // Fallback for hover before first point
            if (actualPointTime == null && trendData.length > 0) {
                actualPointTime = trendData[0].t;
                state = trendData[0].v;
            }

            cursorLine.style.display = "block";
            cursorLine.setAttribute("x1", px_svg); cursorLine.setAttribute("x2", px_svg);

            tooltip.style.display = "block";
            var stTxt = (state === true || state === 1) ? "<span style='color:#4ade80;font-weight:600'>● ONLINE</span>" : "<span style='color:#f87171;font-weight:600'>● OFFLINE</span>";
            var displayTime = actualPointTime ? new Date(actualPointTime).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : "--:--";

            tooltip.innerHTML = "<div style='line-height:1.2'>" + stTxt + "<br/><span style='font-size:10px;opacity:0.7'>" + displayTime + "</span></div>";

            var tw = tooltip.offsetWidth;
            var tx = (mx_screen + 10);
            if (mx_screen > mRect.width / 2) tx = (mx_screen - tw - 10);

            tooltip.style.left = tx + "px";
            tooltip.style.top = (sy(state) * (mRect.height / CH) - 20) + "px";
        };
        svg.onmouseleave = function () { cursorLine.style.display = "none"; tooltip.style.display = "none"; };
    }

    function loadHistory() {
        var now_ts = Date.now();
        var from_ts = now_ts - 12 * 60 * 60 * 1000;
        try {
            U.readHist(base + ".connect", from_ts, now_ts, function (raw) {
                // Apply 5-minute grouping
                trendData = U.group5Minutes(raw);
                U.log("Drawing " + trendData.length + " grouped points (1h goal is ~12)");
                buildTrend(from_ts, now_ts);
            });
        } catch (e) { U.log("Error loading 1h history", e); }
    }

    loadHistory();
    if (svg._refreshT) clearInterval(svg._refreshT);
    svg._refreshT = setInterval(loadHistory, 60 * 1000);
};

// --- PAC Fullscreen Dashboard Implementation ---
HeaderCards.showPACFullscreen = function (base, initialPacAddr, doc, pacList) {
    if (!initialPacAddr) return;
    var U = HeaderGlobals.UTILS;
    var d = doc || document;
    var fsSubs = [];
    var activePAC = initialPacAddr;
    var currentTimeRange = 3600000; // Default 1H
    var trendBuffer = { v: [null, null, null], i: [null, null, null] };
    var inDe, inA; // Support clearing from preset buttons

    function x(tag) {
        try {
            return d.createElement(tag);
        } catch (_) {
            try {
                return d.createElementNS("http://www.w3.org/2000/xhtml", tag);
            } catch (__) {
                return null;
            }
        }
    }
    function setS(el, styles) {
        if (!el || !styles) return;
        for (var k in styles) if (Object.prototype.hasOwnProperty.call(styles, k)) el.style[k] = styles[k];
    }

    // Create Overlay
    var overlay = x("div");
    overlay.id = "pac_fs_overlay";
    setS(overlay, {
        position: "fixed",
        top: "0",
        left: "0",
        width: "100vw",
        height: "100vh",
        background: "#0f172a",
        zIndex: "100000",
        display: "flex",
        flexDirection: "column",
        fontFamily: "'Inter', Arial, sans-serif",
        color: "#f8fafc",
    });

    // Header Container
    var header = x("div");
    setS(header, {
        padding: "15px 40px",
        background: "#1e293b",
        borderBottom: "1px solid #334155",
        display: "flex",
        justifyContent: "space-between",
        alignItems: "center",
        boxShadow: "0 4px 6px -1px rgba(0,0,0,0.1)",
    });

    var leftSide = x("div");
    setS(leftSide, { display: "flex", alignItems: "center" });

    var title = x("div");
    setS(title, { fontSize: "18px", fontWeight: "800", color: "#60a5fa", letterSpacing: "-0.025em", marginRight: "30px" });
    title.textContent = "ENERGÍA (PAC)";
    leftSide.appendChild(title);

    // PAC Selection Tabs
    var tabContainer = x("div");
    setS(tabContainer, { display: "flex", gap: "8px" });
    if (pacList && pacList.length > 0) {
        pacList.forEach(function (pac) {
            var btn = x("button");
            btn.textContent = pac.name.replace(/_/g, " ");
            setS(btn, {
                padding: "6px 14px", borderRadius: "6px", border: "1px solid #334155",
                background: pac.address === activePAC ? "#3b82f6" : "#0f172a",
                color: "#fff", fontSize: "12px", fontWeight: "600", cursor: "pointer", transition: "all 0.2s"
            });
