    var lblDe = x("span");
    lblDe.textContent = "DE:";
    setS(lblDe, {
        color: "#e2e8f0", fontSize: "11px", fontWeight: "700",
        textTransform: "uppercase", letterSpacing: "0.5px"
    });

    inDe = x("input");
    inDe.type = "date";
    setS(inDe, {
        background: "#334155", color: "#fff",
        border: "1px solid #475569", borderRadius: "6px",
        padding: "6px 10px", fontSize: "12px", fontWeight: "500",
        cursor: "pointer", transition: "all 0.2s",
        minWidth: "140px"
    });
    inDe.onfocus = function () { setS(this, { borderColor: "#3b82f6", background: "#1e293b" }); };
    inDe.onblur = function () { setS(this, { borderColor: "#475569", background: "#334155" }); };

    var lblA = x("span");
    lblA.textContent = "A:";
