    });

    inA = x("input");
    inA.type = "date";
    setS(inA, {
        background: "#334155", color: "#fff",
        border: "1px solid #475569", borderRadius: "6px",
        padding: "6px 10px", fontSize: "12px", fontWeight: "500",
