    inA.onblur = function () { setS(this, { borderColor: "#475569", background: "#334155" }); };

    var btnGo = x("button"); btnGo.textContent = "APLICAR";
    setS(btnGo, {
        background: "#10b981", color: "#fff", border: "none", borderRadius: "4px", padding: "4px 10px",
        cursor: "pointer", fontSize: "10px", fontWeight: "800", transition: "all 0.2s"
    });
    btnGo.onclick = function () {
        if (!inDe.value || !inA.value) return;
        var d1 = new Date(inDe.value + "T00:00:00").getTime();
        var d2 = new Date(inA.value + "T23:59:59").getTime();
        if (d1 > d2) return;

        // Reset preset buttons UI
