    dateContainer.appendChild(lblDe); dateContainer.appendChild(inDe);
    dateContainer.appendChild(lblA); dateContainer.appendChild(inA);
    dateContainer.appendChild(btnGo);
    leftSide.appendChild(dateContainer);

    header.appendChild(leftSide);

    // Right Side: Info + Control
    var rightSide = x("div");
    setS(rightSide, { display: "flex", alignItems: "center", gap: "20px" });

    var pacNameLabel = x("div");
    pacNameLabel.id = "fs_pac_name_label";
    setS(pacNameLabel, { fontSize: "15px", fontWeight: "700", color: "#94a3b8" });
    pacNameLabel.textContent = "Detectando...";
    rightSide.appendChild(pacNameLabel);

    var btnClose = x("button");
    btnClose.textContent = "✕ CERRAR";
    setS(btnClose, {
        padding: "8px 20px", border: "1px solid #ef4444", borderRadius: "8px",
        background: "transparent", color: "#ef4444", fontSize: "11px", fontWeight: "800", cursor: "pointer"
    });
    btnClose.onmouseenter = function () { setS(this, { background: "#ef4444", color: "#fff" }); };
    btnClose.onmouseleave = function () { setS(this, { background: "transparent", color: "#ef4444" }); };
    btnClose.onclick = function () { exitFS(); };
    rightSide.appendChild(btnClose);
    header.appendChild(rightSide);
    overlay.appendChild(header);

    // Dashboard Content
    var content = x("div");
    setS(content, { flex: "1", padding: "30px 40px", overflowY: "auto", display: "flex", flexDirection: "column", gap: "30px" });

    function createRow(titleText) {
        var row = x("div");
        setS(row, { display: "flex", flexDirection: "column", gap: "10px" });
        var lbl = x("div");
        lbl.textContent = titleText;
        setS(lbl, { fontSize: "14px", fontWeight: "800", color: "#64748b", textTransform: "uppercase", letterSpacing: "0.1em" });
        row.appendChild(lbl);
        var grid = x("div");
        setS(grid, { display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(300px, 1fr))", gap: "20px" });
        row.appendChild(grid);
        return { row: row, grid: grid };
    }

    var vRow = createRow("Voltajes de Fase (V)");
    var iRow = createRow("Corrientes de Fase (A)");
    var pRow = createRow("Factor de Potencia y Potencia Activa");
    var eRow = createRow("Energía Acumulada");

    content.appendChild(vRow.row);
    content.appendChild(iRow.row);
    content.appendChild(pRow.row);
    content.appendChild(eRow.row);
    overlay.appendChild(content);

    function createMetricCard(title, id, unitSymbol) {
        var card = x("div");
        setS(card, { background: "#1e293b", padding: "20px", borderRadius: "12px", border: "1px solid #334155", position: "relative", overflow: "hidden" });

        var header = x("div");
        setS(header, { display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: "15px", position: "relative", zIndex: "2" });

        var info = x("div");
        var l = x("div"); l.textContent = title; setS(l, { fontSize: "12px", fontWeight: "700", color: "#94a3b8" });
        var v = x("div"); v.id = id; v.textContent = "--"; setS(v, { fontSize: "32px", fontWeight: "900", color: "#fff", marginTop: "4px" });
        info.appendChild(l); info.appendChild(v);
        header.appendChild(info);

        var unit = x("div");
        unit.textContent = unitSymbol;
        setS(unit, { fontSize: "14px", fontWeight: "800", color: "#475569", background: "#0f172a", padding: "4px 10px", borderRadius: "6px" });
        header.appendChild(unit);
        card.appendChild(header);

        var spark = U.x(d, "svg");
        spark.id = id + "_spark";
        setS(spark, { width: "100%", height: "60px", display: "block", background: "rgba(15, 23, 42, 0.3)", borderRadius: "6px" });
        card.appendChild(spark);

        var tip = x("div");
        tip.id = id + "_tip";
        setS(tip, {
            position: "absolute", display: "none", background: "rgba(15, 23, 42, 0.95)",
            color: "#fff", padding: "8px 12px", borderRadius: "8px", fontSize: "12px",
            pointerEvents: "none", zIndex: "100", border: "1px solid #475569",
            boxShadow: "0 10px 15px -3px rgba(0,0,0,0.5)", whiteSpace: "nowrap"
        });
        card.appendChild(tip);

        return card;
    }

    // Grid Builders
    vRow.grid.appendChild(createMetricCard("L1 - L2", "fsv_v12", "V"));
    vRow.grid.appendChild(createMetricCard("L2 - L3", "fsv_v23", "V"));
    vRow.grid.appendChild(createMetricCard("L3 - L1", "fsv_v31", "V"));
    vRow.grid.appendChild(createMetricCard("PROMEDIO", "fsv_vavg", "V"));

    iRow.grid.appendChild(createMetricCard("L1", "fsv_i1", "A"));
    iRow.grid.appendChild(createMetricCard("L2", "fsv_i2", "A"));
    iRow.grid.appendChild(createMetricCard("L3", "fsv_i3", "A"));
    iRow.grid.appendChild(createMetricCard("PROMEDIO", "fsv_iavg", "A"));

    pRow.grid.appendChild(createMetricCard("FACTOR DE POTENCIA", "fsv_fp", "FP"));
    pRow.grid.appendChild(createMetricCard("POTENCIA ACTIVA", "fsv_pact", "KW"));

    eRow.grid.appendChild(createMetricCard("ENERGÍA IMPORTADA", "fsv_eimp", "KWH"));

    var host = d.body || d.documentElement;
    if (host) host.appendChild(overlay);

    function drawSpark(id, points) {
        var svg = d.getElementById(id + "_spark");
        if (!svg) return;
        while (svg.firstChild) svg.removeChild(svg.firstChild);

        // Ensure sorted by time (asc)
        points = (Array.isArray(points) ? points : []).slice().sort(function (a, b) {
            return +a.t - +b.t;
        });

        if (!points || points.length < 2) {
            var txt = d.createElementNS("http://www.w3.org/2000/svg", "text");
            txt.textContent = "SIN DATOS";
            txt.setAttribute("x", "50%"); txt.setAttribute("y", "50%");
            txt.setAttribute("text-anchor", "middle"); txt.setAttribute("dominant-baseline", "middle");
            txt.setAttribute("fill", "#475569"); txt.setAttribute("font-size", "10px");
            txt.setAttribute("style", "font-weight: 800; opacity: 0.5");
            svg.appendChild(txt);
            return;
        }
        var min = Infinity, max = -Infinity;
        points.forEach(function (p) { if (p.v < min) min = p.v; if (p.v > max) max = p.v; });
        if (max === min) { min -= 1; max += 1; }
        var range = max - min;
        var W = 300, H = 60;
        svg.setAttribute("viewBox", "0 0 " + W + " " + H);
        svg.setAttribute("preserveAspectRatio", "none");

        var pathData = "M 0 " + (H - ((points[0].v - min) / range) * H);
        for (var i = 1; i < points.length; i++) {
            var xPos = (i / (points.length - 1)) * W;
            var yPos = H - ((points[i].v - min) / range) * H;
            pathData += " L " + xPos + " " + yPos;
        }

        var path = d.createElementNS("http://www.w3.org/2000/svg", "path");
        path.setAttribute("d", pathData);
        path.setAttribute("stroke", "#3b82f6");
        path.setAttribute("stroke-width", "2");
        path.setAttribute("fill", "none");
        svg.appendChild(path);

        var areaData = pathData + " L " + W + " " + H + " L 0 " + H + " Z";
        var area = d.createElementNS("http://www.w3.org/2000/svg", "path");
        area.setAttribute("d", areaData);
        area.setAttribute("fill", "url(#grad_blue)");
        area.setAttribute("opacity", "0.2");
        svg.appendChild(area);

        var cursorLine = d.createElementNS("http://www.w3.org/2000/svg", "line");
        cursorLine.setAttribute("x1", 0); cursorLine.setAttribute("x2", 0);
        cursorLine.setAttribute("y1", 0); cursorLine.setAttribute("y2", H);
        cursorLine.setAttribute("stroke", "#fff"); cursorLine.setAttribute("stroke-width", "1");
        cursorLine.setAttribute("stroke-dasharray", "2,2"); cursorLine.style.display = "none";
        svg.appendChild(cursorLine);

        var cardTip = d.getElementById(id + "_tip");

        svg.onmousemove = function (e) {
            var ev = e || window.event;
            var rect = svg.getBoundingClientRect();
            var mx = ev.clientX - rect.left;
            var ratio = Math.max(0, Math.min(1, mx / rect.width));
            var idx = Math.round(ratio * (points.length - 1));
            var p = points[idx];
            if (!p) return;

            cursorLine.style.display = "block";
            var px = (idx / (points.length - 1)) * W;
            cursorLine.setAttribute("x1", px); cursorLine.setAttribute("x2", px);

            if (cardTip) {
                cardTip.style.display = "block";
                var dt = new Date(p.t);
                var dateStr = dt.toLocaleDateString([], { day: '2-digit', month: '2-digit' });
                var timeStr = dt.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: true });
                var valStr = p.v.toFixed(id.indexOf("eimp") > -1 ? 0 : 1);
                cardTip.innerHTML = "<div style='font-weight:800;font-size:14px;'>" + valStr + "</div><div style='font-size:10px;opacity:0.8;text-transform:uppercase;'>" + dateStr + " " + timeStr + "</div>";

                var tw = cardTip.offsetWidth;
                var tx = mx + 15;
                if (tx + tw > rect.width) tx = mx - tw - 15;
                cardTip.style.left = tx + "px";
                cardTip.style.top = "10px";
            }
        };

        svg.onmouseleave = function () {
            cursorLine.style.display = "none";
            if (cardTip) cardTip.style.display = "none";
        };

        if (!d.getElementById("grad_blue")) {
            var defs = d.createElementNS("http://www.w3.org/2000/svg", "defs");
            var lg = d.createElementNS("http://www.w3.org/2000/svg", "linearGradient");
            lg.id = "grad_blue"; lg.setAttribute("x1", "0%"); lg.setAttribute("y1", "0%"); lg.setAttribute("x2", "0%"); lg.setAttribute("y2", "100%");
            var s1 = d.createElementNS("http://www.w3.org/2000/svg", "stop"); s1.setAttribute("offset", "0%"); s1.setAttribute("stop-color", "#3b82f6");
            var s2 = d.createElementNS("http://www.w3.org/2000/svg", "stop"); s2.setAttribute("offset", "100%"); s2.setAttribute("stop-color", "#3b82f6"); s2.setAttribute("stop-opacity", "0");
            lg.appendChild(s1); lg.appendChild(s2); defs.appendChild(lg); svg.appendChild(defs);
        }
    }

    function switchToPAC(pacAddr, fallbackName, customFrom, customTo) {
        fsSubs.forEach(function (s) { webMI.data.unsubscribe(s); });
        fsSubs = [];
        activePAC = pacAddr;
        trendBuffer = { v: [null, null, null], i: [null, null, null] };

        var pacLabel = d.getElementById("fs_pac_name_label");
        if (pacLabel) pacLabel.textContent = (fallbackName || "Cargando...").replace(/_/g, " ");

        var nodeMap = [
            { n: "Voltaje_L1-L2_Historico", id: "fsv_v12", type: "v", idx: 0 },
            { n: "Voltaje_L2-L3_Historico", id: "fsv_v23", type: "v", idx: 1 },
            { n: "Voltaje_L3-L1_Historico", id: "fsv_v31", type: "v", idx: 2 },
            { n: "Corriente_L1_Historico", id: "fsv_i1", type: "i", idx: 0 },
            { n: "Corriente_L2_Historico", id: "fsv_i2", type: "i", idx: 1 },
            { n: "Corriente_L3_Historico", id: "fsv_i3", type: "i", idx: 2 },
            { n: "FP_Historico", id: "fsv_fp" },
            { n: "Potencia_Activa_Historico", id: "fsv_pact" },
            { n: "Energia_Importada_Historico", id: "fsv_eimp" }
        ];

        var vals = { v1: 0, v2: 0, v3: 0, i1: 0, i2: 0, i3: 0 };

        function updateAvgs() {
            var vAvg = (vals.v1 + vals.v2 + vals.v3) / 3;
            var iAvg = (vals.i1 + vals.i2 + vals.i3) / 3;
            var elV = d.getElementById("fsv_vavg"); if (elV) elV.textContent = vAvg.toFixed(1);
            var elI = d.getElementById("fsv_iavg"); if (elI) elI.textContent = iAvg.toFixed(1);
        }

        nodeMap.forEach(function (item) {
            var path = pacAddr + "." + item.n;

            function updateUI(val) {
                if (val == null) return;
                var v = parseFloat(val);
                var el = d.getElementById(item.id);
                if (el) el.textContent = v.toFixed(item.id === "fsv_eimp" ? 0 : 1);
                if (item.id === "fsv_v12") vals.v1 = v;
                if (item.id === "fsv_v23") vals.v2 = v;
                if (item.id === "fsv_v31") vals.v3 = v;
                if (item.id === "fsv_i1") vals.i1 = v;
                if (item.id === "fsv_i2") vals.i2 = v;
                if (item.id === "fsv_i3") vals.i3 = v;
                updateAvgs();
            }

            // Real-time Update via Historical subscription (if it triggers)
            fsSubs.push(webMI.data.subscribe(path, function (r) { if (r && r.value != null) updateUI(r.value); }));

            // NEW: Use Standard Helper
            var now_ts = Date.now();
            var from_ts = customFrom || (now_ts - currentTimeRange);
            var to_ts = customTo || now_ts;

            // Ensure integers (keep in milliseconds)
            from_ts = Math.floor(from_ts);
            to_ts = Math.floor(to_ts);

            // console.log("[PAC Query]", item.id, ...);

            U.readHist(path, from_ts, to_ts, function (raw) {
                // console.log("[PAC Result]", item.id, ...);
                if (raw && raw.length > 0) {
                    drawSpark(item.id, raw);
                    updateUI(raw[raw.length - 1].v);
                    if (item.type != null) {
                        trendBuffer[item.type][item.idx] = raw;
                        checkAndDrawAverage(item.type);
                    }
                } else {
                    drawSpark(item.id, []);
                }
            });
        });

        function checkAndDrawAverage(type) {
            var b = trendBuffer[type];
            if (b[0] && b[1] && b[2]) {
                var len = Math.min(b[0].length, b[1].length, b[2].length);
                var avgPts = [];
                for (var k = 0; k < len; k++) {
                    avgPts.push({ t: b[0][k].t, v: (b[0][k].v + b[1][k].v + b[2][k].v) / 3 });
                }
                drawSpark(type === "v" ? "fsv_vavg" : "fsv_iavg", avgPts);
                updateUIForAvg(type, avgPts[avgPts.length - 1].v);
            }
        }

        function updateUIForAvg(type, val) {
            var el = d.getElementById(type === "v" ? "fsv_vavg" : "fsv_iavg");
            if (el) el.textContent = val.toFixed(1);
        }

        webMI.data.read(pacAddr + ".nombre", function (r) { if (r && r.value != null && pacLabel) pacLabel.textContent = r.value.replace(/_/g, " "); });
        fsSubs.push(webMI.data.subscribe(pacAddr + ".nombre", function (r) { if (r && r.value != null && pacLabel) pacLabel.textContent = r.value.replace(/_/g, " "); }));
    }

    // Fullscreen API
    function enterFS(el) { try { if (el.requestFullscreen) el.requestFullscreen(); else if (el.webkitRequestFullscreen) el.webkitRequestFullscreen(); } catch (_) { } }
    function exitFS() { try { if (d.exitFullscreen) d.exitFullscreen(); else if (d.webkitExitFullscreen) d.webkitExitFullscreen(); } catch (_) { } }
    function onFsChange() {
        var fsEl = d.fullscreenElement || d.webkitFullscreenElement || d.mozFullScreenElement;
        if (!fsEl) {
            d.removeEventListener("fullscreenchange", onFsChange);
            if (overlay && overlay.parentNode) overlay.parentNode.removeChild(overlay);
            fsSubs.forEach(function (s) { webMI.data.unsubscribe(s); });
        }
    }
    d.addEventListener("fullscreenchange", onFsChange);
    enterFS(overlay);
    switchToPAC(activePAC, (pacList.filter(function (p) { return p.address === activePAC; })[0] || {}).name);
};

// Historical data fetching moved to global HeaderGlobals.UTILS.readHist

HeaderCards.showTankFullscreen = function (base, doc) {
    var U = HeaderGlobals.UTILS;
    var d = doc || document;
    var tfVal = null; // Calculated Total Flow display
    var volVal = null; // Calculated Total Volume display
    U.log("Starting showTankFullscreen setup for:", base);
    var baseName = base.toLowerCase();
    var isAR = (baseName.indexOf("cuenca") >= 0 || baseName.indexOf("carcamo") >= 0 || baseName.indexOf("residual") >= 0);
    if (baseName.indexOf("circuito") >= 0 || baseName.indexOf("tanque") >= 0 || baseName.indexOf("potable") >= 0) isAR = false;

    function getCleanSiteName(raw) {
        if (!raw) return "";
        var name = raw.replace(/_/g, " ").replace(/^[0-9]+:\s*/, "");
        // Strip away Redundant categories to show ONLY the object name
        name = name.replace(/Tanque\s?/gi, "").replace(/Cárcamo\s?|Carcamo\s?/gi, "").trim();
        return name;
    }

    function getCleanGroupName(raw) {
        if (!raw) return "";
        var parts = raw.split(".");
        // If the path ends in a specific site, the group name is usually the parent
        var name = parts.pop();
        if ((name.indexOf("Tanque") >= 0 || name.indexOf("Carcamo") >= 0 || name.indexOf("Potable") >= 0 || name.indexOf("Residual") >= 0) && parts.length > 0) {
            name = parts.pop();
        }

        if (name.indexOf("_CAP_") >= 0) {
            // "Circuito_CAP_001" -> "Circuito 001"
            name = name.replace(/_CAP_/g, " ").replace(/_/g, " ");
        } else {
            name = name.replace(/_/g, " ");
        }
        return name;
    }

    function x(tag) {
        var t = (tag || "").toLowerCase();
        try {
            if (["svg", "path", "circle", "g", "rect", "text", "line", "image", "linearGradient", "stop", "defs", "tspan"].indexOf(t) >= 0) {
                return d.createElementNS("http://www.w3.org/2000/svg", t);
            }
            return d.createElement(t);
        } catch (_) {
            try { return d.createElementNS("http://www.w3.org/1999/xhtml", t); } catch (__) { return null; }
        }
    }

    function setS(el, styles) {
        if (!el || !styles) return;
        for (var k in styles) if (Object.prototype.hasOwnProperty.call(styles, k)) el.style[k] = styles[k];
    }

    // --- CSS ENHANCEMENTS (Phase 75) ---
    var style = x("style");
    style.textContent = [
        ".custom-scroll::-webkit-scrollbar { width: 6px; }",
        ".custom-scroll::-webkit-scrollbar-track { background: rgba(0,0,0,0.2); }",
        ".custom-scroll::-webkit-scrollbar-thumb { background: #3b82f6; border-radius: 3px; }",
        ".progress-bar-container { position: absolute; top: 0; left: 0; width: 100%; height: 3px; background: rgba(255,255,255,0.05); z-index: 10001; }",
        ".progress-bar-fill { height: 100%; width: 0%; background: linear-gradient(90deg, #3b82f6, #60a5fa); transition: width 0.3s ease; }",
        "@media print {",
        "  @page { size: auto; margin: 10mm; }",
        "  body * { visibility: hidden; }",
        "  #tank_fs_overlay, #tank_fs_overlay * { visibility: visible; }",
