    btnExport.disabled = true;
    btnExport.onclick = function () {
        var win = window;
        function tryPrint(w) {
            try {
                if (w && w.print) {
                    w.print.call(w);
                    return true;
                }
            } catch (e) { }
            try {
                if (w && w.print) {
                    w.print();
                    return true;
                }
            } catch (e) { }
            return false;
        }

        // Strategy: Decouple with setTimeout and try various contexts
        setTimeout(function () {
            if (tryPrint(window)) return;
            if (tryPrint(self)) return;
            if (tryPrint(top)) return;
            if (tryPrint(parent)) return;

            // Final desperate attempt: execCommand
            try {
                document.execCommand('print', false, null);
            } catch (e) {
                // error handled
                alert("No se pudo abrir el diálogo de impresión. El sistema SCADA puede estar restringiendo esta función.");
