    // --- State & Logic ---
    var currentMode = null; // local | circuit
    var activeSeries = [];
    var timeRange = 12; // hours
    var configNode = base + ".dashboard_config";

    function saveConfig() {
        var data = JSON.stringify({ mode: currentMode, range: timeRange });
        webMI.data.write(configNode, data);
    }

    function loadConfig(cb) {
        webMI.data.read(configNode, function (res) {
            var val = res && (typeof res.value !== "undefined" ? res.value : res);
            if (!val || val === "null") { if (cb) cb(); return; }
            try {
                var cfg = JSON.parse(val);
                if (cfg.mode) currentMode = cfg.mode;
                if (cfg.range) timeRange = cfg.range;
            } catch (e) { }
            if (cb) cb();
        });
    }

    function updatePumps(externalData) {
        var processPumps = function (data) {
            pumpList.innerHTML = "";
            var pumps = data.pumps || [];
            if (pumps.length === 0) {
                pumpList.innerHTML = '<div style="color:#64748b; font-size:12px; font-style:italic;">No se detectaron bombas</div>';
                return;
            }
            pumps.forEach(function (p) {
                var pItem = x("div");
                setS(pItem, { background: "#1e293b", padding: "10px", borderRadius: "8px", marginBottom: "8px", display: "flex", alignItems: "center", gap: "10px" });

                var stave = x("div"); setS(stave, { width: "10px", height: "24px", display: "flex", flexDirection: "column", gap: "1px", borderRadius: "2px", overflow: "hidden" });
                var bE = x("div"); setS(bE, { flex: "1", background: "#475569" });
                var bM = x("div"); setS(bM, { flex: "1", background: "#475569" });
                var bL = x("div"); setS(bL, { flex: "1", background: "#475569" });
                stave.appendChild(bE); stave.appendChild(bM); stave.appendChild(bL);

                var pName = x("span");
                var cleanName = getCleanSiteName(p.name);
                var siteCleanName = getCleanSiteName(p.siteName);
                pName.innerHTML = (siteCleanName ? '<small style="color:#64748b; display:block; font-size:9px; font-weight:900;">' + siteCleanName.toUpperCase() + '</small>' : '') + cleanName;
                setS(pName, { fontSize: "12px", fontWeight: "bold", lineHeight: "1.1" });

                var badges = x("div"); setS(badges, { marginLeft: "auto", display: "flex", gap: "4px" });
                var bLocalOff = x("div"); setS(bLocalOff, { background: "#ef4444", color: "white", fontSize: "9px", fontWeight: "900", padding: "3px 8px", borderRadius: "4px", textTransform: "uppercase", display: "none" });
                bLocalOff.textContent = "EQUIPO FUERA";
                var bFault = x("div"); setS(bFault, { background: "#ef4444", color: "white", fontSize: "9px", fontWeight: "900", padding: "3px 8px", borderRadius: "4px", textTransform: "uppercase", display: "none" });
                bFault.textContent = "FALLA";
                badges.appendChild(bLocalOff); badges.appendChild(bFault);

                pItem.appendChild(stave); pItem.appendChild(pName); pItem.appendChild(badges);
                pumpList.appendChild(pItem);

                var sPath = p.address;
                if (sPath.indexOf("s=") >= 0) sPath = sPath.slice(sPath.indexOf("s=") + 2);
                var pNameKey = cleanName;
                if (!HeaderCards.equipmentLiveStates[pNameKey]) HeaderCards.equipmentLiveStates[pNameKey] = { maint: false, fault: false, e: 0, l: 0 };

                U.addSub(sPath + ".maintenance", function (e) {
                    HeaderCards.equipmentLiveStates[pNameKey].maint = !!(e && e.value);
                }, overlay._subs);
                U.addSub(sPath + ".fault", function (e) {
                    var isFault = !!(e && e.value);
                    HeaderCards.equipmentLiveStates[pNameKey].fault = isFault;
                    bFault.style.display = isFault ? "block" : "none";
                    if (HeaderCards.chartBadges[pNameKey] && HeaderCards.chartBadges[pNameKey].fault) {
                        HeaderCards.chartBadges[pNameKey].fault.style.display = isFault ? "block" : "none";
                    }
                }, overlay._subs);

                var pState = { e: 0, l: 0 };
                function updStave() {
                    var isOn = (pState.e == 1 || pState.e == 2 || pState.e == 5);
                    var isLoc = (pState.l == 1 || pState.l == 2 || pState.l == 5);
                    var isLocalOff = isLoc && !isOn;
                    if (isLocalOff) { bE.style.background = "#ef4444"; }
                    else { bE.style.background = isOn ? "#22c55e" : "#475569"; }
                    bL.style.background = isLoc ? "#f97316" : "#06b6d4";
                    bLocalOff.style.display = isLocalOff ? "block" : "none";

                    if (HeaderCards.chartBadges[pNameKey] && HeaderCards.chartBadges[pNameKey].localOff) {
                        HeaderCards.chartBadges[pNameKey].localOff.style.display = isLocalOff ? "block" : "none";
                    }
                }

                U.addAlarmSub(sPath + ".Alarma_Estatus.ON_OFF.Estatus", function (e) {
                    var s = (e && e.state != null ? e.state : 0);
                    pState.e = s;
                    HeaderCards.equipmentLiveStates[pNameKey].e = s;
                    updStave();
                }, overlay._subs);
                U.addAlarmSub(sPath + ".Alarma_ManAuto.Manual_Automatico.Manual_Automatico", function (e) {
                    var s = (e && e.state != null ? e.state : 0);
                    bM.style.background = (s == 1 || s == 2 || s == 5) ? "#eab308" : "#3b82f6";
                }, overlay._subs);
                U.addAlarmSub(sPath + ".Alarma_Local.LR.Estado", function (e) {
                    var s = (e && e.state != null ? e.state : 0);
                    pState.l = s;
                    HeaderCards.equipmentLiveStates[pNameKey].l = s;
                    updStave();
                }, overlay._subs);
            });
        };

        if (externalData) processPumps(externalData);
        else U.discoverEquipment(base, processPumps);
    }

    // --- Chart Core ---
    // chartSVG original will be removed in favor of dynamic containers in drawMultiChart

    function drawMultiChart(datasets, forcedFrom, forcedNow) {
        if (!overlay.parentNode) return;
        var scrollPos = chartCanvas.scrollTop;
        chartCanvas.innerHTML = ""; // Clear for new rendering
        HeaderCards.chartBadges = {}; // Reset badges
        if (!datasets || datasets.length === 0) return;

        // Group datasets by site
        var siteGroups = {};
        datasets.forEach(function (ds) {
            var s = ds.site || "Local";
            if (!siteGroups[s]) siteGroups[s] = [];
            siteGroups[s].push(ds);
        });

        var sites = Object.keys(siteGroups).sort();
        sites.forEach(function (siteName) {
            var siteDatasets = siteGroups[siteName];

            // Site Wrapper (for print paging)
            var siteWrap = x("div");
            siteWrap.className = "site-wrap";
            setS(siteWrap, { marginBottom: "20px", position: "relative" });
            chartCanvas.appendChild(siteWrap);

            // Site Header
            var sHead = x("div");
            setS(sHead, { padding: "10px 15px", background: "rgba(255,255,255,0.03)", borderBottom: "1px solid rgba(255,255,255,0.05)", color: "#94a3b8", fontWeight: "900", fontSize: "11px", letterSpacing: "1px", display: "flex", justifyContent: "space-between", alignItems: "center" });
            sHead.innerHTML = '<span>' + siteName.toUpperCase() + '</span><small style="color:#475569; font-weight:400">' + (currentMode === "circuit" ? "VISTA REPORTE" : "VISTA SITIO") + '</small>';
            siteWrap.appendChild(sHead);

            var sBody = x("div"); setS(sBody, { position: "relative", marginBottom: "10px", background: "#020617" });
            siteWrap.appendChild(sBody);

            var siteSVG = x("svg"); setS(siteSVG, { width: "100%", height: "auto", display: "block" });
            sBody.appendChild(siteSVG);

            renderOneChart(siteSVG, siteDatasets, sBody, forcedFrom, forcedNow);
        });

        // RESTORE SCROLL
        setTimeout(function () {
            chartCanvas.scrollTop = scrollPos;
        }, 0);
    }

    function renderOneChart(chartSVG, datasets, container, forcedFrom, forcedNow) {
        var meta = { tank: { label: "Nivel", unit: "%" }, chlorine: { label: "Cloro", unit: "ppm" }, flow: { label: "Caudal", unit: "l/s" }, pressure: { label: "Presión", unit: "bar" }, status: { label: "Motores", unit: "I/O" }, other: { label: "Otros", unit: "" } };
        var groups = {}; var pumpGroups = {};
        datasets.forEach(function (ds) {
            if (ds.disabled) return;
            var isStatus = ds.type && ds.type.toLowerCase().indexOf("status") >= 0;
            var g = isStatus ? "status" : (ds.type || "other");
            if (!groups[g]) groups[g] = { min: Infinity, max: -Infinity, items: [], unit: "" };
            groups[g].items.push(ds);
            if (!isStatus) {
                ds.data.forEach(function (p) { if (p.v < groups[g].min) groups[g].min = p.v; if (p.v > groups[g].max) groups[g].max = p.v; });
                if (g === "tank") { groups[g].min = 0; groups[g].max = 100; }
                else if (groups[g].max !== -Infinity) { if (groups[g].min > 0) groups[g].min = 0; groups[g].max *= 1.2; }
            } else {
                groups[g].min = 0; groups[g].max = 1;
                var eqName = ds.equip || ds.name.split(" (")[0];
                var eqKey = ds.type.indexOf("_") > 0 ? ds.type.split("_")[1] : (ds.name.indexOf("(Marcha)") >= 0 ? "e" : (ds.name.indexOf("(Modo)") >= 0 ? "m" : "l"));
                if (!pumpGroups[eqName]) pumpGroups[eqName] = { e: null, m: null, l: null };
                pumpGroups[eqName][eqKey] = ds;
            }
        });

        var CW = 900; var equipKeys = Object.keys(pumpGroups).sort(); var pumpAreaH = equipKeys.length * 160; var mainBaseline = 350; var padT = 30, padB = 40, padL = 150, padR = 80; var CH = mainBaseline + pumpAreaH + (equipKeys.length > 0 ? 100 : 50);
        chartSVG.setAttribute("viewBox", "0 0 " + CW + " " + CH); var canvasW = container.clientWidth || 900; chartSVG.style.height = (CH * (canvasW / CW)) + "px";
        var nowMs = forcedNow || Date.now(); var fromMs = forcedFrom || (nowMs - timeRange * 3600000);
        var sx = function (t) { return padL + (CW - padL - padR) * (t - fromMs) / (nowMs - fromMs); };

        var xLine = x("line"); xLine.setAttribute("x1", padL); xLine.setAttribute("y1", mainBaseline); xLine.setAttribute("x2", CW - padR); xLine.setAttribute("y2", mainBaseline); xLine.setAttribute("stroke", "#475569"); chartSVG.appendChild(xLine);
        for (var i = 0; i <= 6; i++) {
            var t = fromMs + (i * (nowMs - fromMs) / 6); var gx = padL + (i * (CW - padL - padR) / 6);
            var gLine = x("line"); gLine.setAttribute("x1", gx); gLine.setAttribute("y1", padT); gLine.setAttribute("x2", gx); gLine.setAttribute("y2", mainBaseline + 20); gLine.setAttribute("stroke", "rgba(255,255,255,0.05)"); chartSVG.appendChild(gLine);
            var tim = new Date(t); var lbl = x("text"); lbl.textContent = (tim.getHours() < 10 ? "0" : "") + tim.getHours() + ":" + (tim.getMinutes() < 10 ? "0" : "") + tim.getMinutes();
            lbl.setAttribute("x", gx); lbl.setAttribute("y", mainBaseline + 15); lbl.setAttribute("fill", "#64748b"); lbl.setAttribute("font-size", "10px"); lbl.setAttribute("text-anchor", "middle"); chartSVG.appendChild(lbl);
        }

        Object.keys(groups).forEach(function (t, idx) {
            var g = groups[t]; if (t === "status") return;
            var isLeft = idx % 2 === 0; var xPos = isLeft ? (padL - 10 - (Math.floor(idx / 2) * 40)) : (CW - padR + 10 + (Math.floor(idx / 2) * 40));
            var axisColor = g.items[0].color;
            var aLine = x("line"); aLine.setAttribute("x1", xPos); aLine.setAttribute("y1", padT); aLine.setAttribute("x2", xPos); aLine.setAttribute("y2", mainBaseline); aLine.setAttribute("stroke", axisColor); aLine.setAttribute("opacity", "0.5"); chartSVG.appendChild(aLine);
            var label = x("text"); label.textContent = (meta[t] ? meta[t].unit : ""); label.setAttribute("x", xPos); label.setAttribute("y", padT - 5); label.setAttribute("fill", axisColor); label.setAttribute("font-size", "10px"); label.setAttribute("text-anchor", "middle"); chartSVG.appendChild(label);
        });

        var getSY = function (v, type) {
            var g = type && type.toLowerCase().indexOf("status") >= 0 ? "status" : (type || "other"); var rg = groups[g]; if (!rg) return mainBaseline;
            var min = rg.min, max = rg.max; if (max === min) return mainBaseline - (mainBaseline - padT) / 2;
            return mainBaseline - (v - min) / (max - min) * (mainBaseline - padT);
        };

        datasets.forEach(function (ds) {
            if (ds.disabled || (ds.type && ds.type.indexOf("status_") === 0)) return;
            if (!ds.data || ds.data.length < 1) return;
            var pathStr = "M " + sx(ds.data[0].t) + " " + getSY(ds.data[0].v, ds.type);
            for (var i = 1; i < ds.data.length; i++) pathStr += " L " + sx(ds.data[i].t) + " " + getSY(ds.data[i].v, ds.type);
            var p = x("path"); p.setAttribute("d", pathStr); p.setAttribute("stroke", ds.color); p.setAttribute("fill", "none"); p.setAttribute("stroke-width", "2"); p.setAttribute("stroke-linejoin", "round"); p.setAttribute("stroke-linecap", "round"); chartSVG.appendChild(p);
            var areaStr = pathStr + " L " + sx(ds.data[ds.data.length - 1].t) + " " + mainBaseline + " L " + sx(ds.data[0].t) + " " + mainBaseline + " Z";
            var area = x("path"); area.setAttribute("d", areaStr); area.setAttribute("fill", ds.color); area.setAttribute("opacity", "0.03"); chartSVG.appendChild(area);
        });

        equipKeys.forEach(function (eqName, equipIdx) {
            var group = pumpGroups[eqName]; var groupY = (mainBaseline + 60) + (equipIdx * 160);
            var bg = x("rect"); bg.setAttribute("x", 15); bg.setAttribute("y", groupY - 25); bg.setAttribute("width", CW - 30); bg.setAttribute("height", 140); bg.setAttribute("fill", "#1e293b"); bg.setAttribute("stroke", "#334155"); bg.setAttribute("rx", "10"); chartSVG.appendChild(bg);
            var dispName = eqName.replace(/Tanque\s?/gi, "").toUpperCase();
            var title = x("text"); title.textContent = dispName; title.setAttribute("x", 35); title.setAttribute("y", groupY - 5); title.setAttribute("fill", "#94a3b8"); title.setAttribute("font-size", "11px"); title.setAttribute("font-weight", "900"); chartSVG.appendChild(title);

            // --- Live Status Badges in Chart area ---
            var pNameKey = getCleanSiteName(eqName);
            var live = HeaderCards.equipmentLiveStates[pNameKey] || { e: 0, l: 0, fault: false };
            HeaderCards.chartBadges[pNameKey] = { localOff: null, fault: null };

            function createSVGBadge(text, color, xPos, w) {
                var width = w || 55;
                var g = x("g");
                var r = x("rect"); r.setAttribute("x", xPos); r.setAttribute("y", groupY - 18); r.setAttribute("width", width); r.setAttribute("height", 16); r.setAttribute("fill", color); r.setAttribute("rx", 4);
                var t = x("text"); t.textContent = text; t.setAttribute("x", xPos + (width / 2)); t.setAttribute("y", groupY - 6); t.setAttribute("fill", "white"); t.setAttribute("font-size", "9px"); t.setAttribute("font-weight", "bold"); t.setAttribute("text-anchor", "middle");
                g.appendChild(r); g.appendChild(t);
                chartSVG.appendChild(g);
                return g;
            }
            var bX = 35 + 120;
            var gLO = createSVGBadge("EQUIPO FUERA", "#ef4444", bX, 75);
            var gF = createSVGBadge("FALLA", "#ef4444", bX + 85, 55);

            var isOn_L = (live.e == 1 || live.e == 2 || live.e == 5);
            var isLoc_L = (live.l == 1 || live.l == 2 || live.l == 5);
            var isLO_L = isLoc_L && !isOn_L;
            gLO.style.display = isLO_L ? "block" : "none";
            gF.style.display = live.fault ? "block" : "none";
            HeaderCards.chartBadges[pNameKey].localOff = gLO;
            HeaderCards.chartBadges[pNameKey].fault = gF;
            // --- End Badges ---

            var trackTopY = groupY + 5, stepH = 16;
            ["e", "m", "l"].forEach(function (key) {
                var ds = group[key]; if (!ds) return;

                // --- ROBUST DATA CLEANUP (Deduplicate & Group by Pixels) ---
                var rawPts = ds.data || [];
                if (rawPts.length > 0) {
                    rawPts.sort(function (a, b) { return a.t - b.t; });
                    // Ensure coverage of the requested range
                    if (rawPts[0].t > fromMs) rawPts.unshift({ t: fromMs, v: rawPts[0].v });
                    if (rawPts[rawPts.length - 1].t < nowMs) rawPts.push({ t: nowMs, v: rawPts[rawPts.length - 1].v });
                } else {
                    rawPts = [{ t: fromMs, v: 0 }, { t: nowMs, v: 0 }];
                }

                // Bucket data by horizontal pixels (matches Connectivity logic)
                var interval = (nowMs - fromMs) / (CW - padL - padR);
                if (interval < 1) interval = 1;
                var trackData = U.groupData(rawPts, interval);

                // Ensure tail end is covered
                if (trackData.length > 0 && trackData[trackData.length - 1].t < nowMs) {
                    trackData.push({ t: nowMs, v: trackData[trackData.length - 1].v });
                }
                // --- END CLEANUP ---

                var rowLbl = x("text"); rowLbl.textContent = (key === "e" ? "ENCENDIDO" : (key === "m" ? "MAN/AUTO" : "LOC/REM")); rowLbl.setAttribute("x", padL - 15); rowLbl.setAttribute("y", trackTopY + (key === "e" ? 32 : (key === "m" ? 60 : 88))); rowLbl.setAttribute("fill", (key === "e" ? "#22c55e" : (key === "m" ? "#3b82f6" : "#06b6d4"))); rowLbl.setAttribute("font-size", "11px"); rowLbl.setAttribute("text-anchor", "end"); rowLbl.setAttribute("font-weight", "900"); chartSVG.appendChild(rowLbl);

                for (var i = 0; i < trackData.length - 1; i++) {
                    var p1 = trackData[i], p2 = trackData[i + 1];
                    var x1 = sx(p1.t), x2 = sx(p2.t);

                    var isOper = (p1.v == 1);
                    var segColor = (key === "e" ? (isOper ? "#22c55e" : "#475569") :
                        (key === "m" ? (isOper ? "#3b82f6" : "#eab308") :
                            (isOper ? "#06b6d4" : "#f97316")));

                    var y1 = trackTopY + (key === "e" ? 20 : (key === "m" ? 48 : 76)) + (isOper ? 0 : stepH);

                    // Horizontal segment (current state until next timestamp)
                    var line = x("line"); line.setAttribute("x1", x1); line.setAttribute("y1", y1); line.setAttribute("x2", x2); line.setAttribute("y2", y1);
                    line.setAttribute("stroke", segColor); line.setAttribute("stroke-width", "2.5"); chartSVG.appendChild(line);

                    // Vertical transition at x2 (from p1.v to p2.v)
                    if (p1.v !== p2.v) {
                        var nextIsOper = (p2.v == 1);
                        var y2 = trackTopY + (key === "e" ? 20 : (key === "m" ? 48 : 76)) + (nextIsOper ? 0 : stepH);
                        // Transition line color matches the NEW state
                        var vCol = (key === "e" ? (nextIsOper ? "#22c55e" : "#475569") :
                            (key === "m" ? (nextIsOper ? "#3b82f6" : "#eab308") :
                                (nextIsOper ? "#06b6d4" : "#f97316")));
                        var vLine = x("line"); vLine.setAttribute("x1", x2); vLine.setAttribute("y1", y1); vLine.setAttribute("x2", x2); vLine.setAttribute("y2", y2);
                        vLine.setAttribute("stroke", vCol); vLine.setAttribute("stroke-width", "2.5"); chartSVG.appendChild(vLine);
                    }
                }
            });
        });

        var cursorLine = x("line"); cursorLine.setAttribute("y1", padT); cursorLine.setAttribute("y2", CH - 20); cursorLine.setAttribute("stroke", "rgba(255,255,255,0.7)"); cursorLine.setAttribute("stroke-width", "1"); cursorLine.setAttribute("stroke-dasharray", "3,3"); cursorLine.style.display = "none"; chartSVG.appendChild(cursorLine);
        var tooltip = container.querySelector(".chart-tooltip"); if (!tooltip) { tooltip = x("div"); tooltip.className = "chart-tooltip"; container.appendChild(tooltip); }
        setS(tooltip, { position: "absolute", display: "none", background: "rgba(15, 23, 42, 0.95)", border: "1px solid rgba(255,255,255,0.15)", borderRadius: "8px", padding: "12px", color: "#fff", fontSize: "11px", pointerEvents: "none", zIndex: "5000", boxShadow: "0 10px 25px rgba(0,0,0,0.6)", minWidth: "180px", backdropFilter: "blur(4px)" });
        chartSVG.onmousemove = function (e) {
            var rect = chartSVG.getBoundingClientRect(); var mx = e.clientX - rect.left, my = e.clientY - rect.top; var plotMx = mx * (CW / rect.width);
            if (plotMx < padL || plotMx > CW - padR) { cursorLine.style.display = "none"; tooltip.style.display = "none"; return; }
            cursorLine.style.display = "block"; cursorLine.setAttribute("x1", plotMx); cursorLine.setAttribute("x2", plotMx);
            var hoverT = fromMs + (plotMx - padL) / (CW - padL - padR) * (nowMs - fromMs);
            var d = new Date(hoverT); var html = "<div style='font-weight:bold; margin-bottom:8px; color:#94a3b8'>" + d.toLocaleString() + "</div>";
            var localY = my * (CH / rect.height); var hoveredPump = null; if (localY >= (mainBaseline + 35)) { var pIdx = Math.floor((localY - (mainBaseline + 35)) / 160); if (pIdx >= 0 && pIdx < equipKeys.length) hoveredPump = equipKeys[pIdx]; }
            if (hoveredPump) {
                html += "<div style='font-weight:bold; color:#fff; border-bottom:1px solid rgba(255,255,255,0.1); padding-bottom:4px; margin-bottom:8px;'>" + hoveredPump + "</div>";
                ["e", "m", "l"].forEach(function (k) {
                    var ds = pumpGroups[hoveredPump][k]; if (!ds) return; var val = 0; ds.data.forEach(function (p) { if (p.t <= hoverT + 1000) val = p.v; });
                    var label = (k === "e" ? "Estado" : (k === "m" ? "Modo" : "Local")); var vText = (k === "e" ? (val == 1 ? "ON" : "OFF") : (k === "m" ? (val == 1 ? "AUTO" : "MAN") : (val == 1 ? "REM" : "LOC")));
                    var vCol = (k === "e" ? (val == 1 ? "#22c55e" : "#94a3b8") : (k === "m" ? (val == 1 ? "#3b82f6" : "#eab308") : (val == 1 ? "#06b6d4" : "#f97316")));
                    html += "<div style='display:flex; justify-content:space-between; gap:10px; margin-bottom:2px;'><span style='color:#64748b'>" + label + ":</span><b style='color:" + vCol + "'>" + vText + "</b></div>";
                });
            } else {
                datasets.forEach(function (ds) {
                    if (ds.disabled || (ds.type && ds.type.indexOf("status") >= 0)) return;
                    var closest = ds.data[0]; var minDist = Infinity;
                    ds.data.forEach(function (p) { var diff = Math.abs(p.t - hoverT); if (diff < minDist) { minDist = diff; closest = p; } });
                    if (closest && minDist < 3600000) html += "<div style='display:flex; justify-content:space-between; gap:20px; margin-bottom:4px;'><span style='color:" + ds.color + "'>● " + ds.name + "</span><b style='color:#fff'>" + closest.v.toFixed(1) + "</b></div>";
                });
            }
            tooltip.style.display = "block"; tooltip.innerHTML = html; var tx = mx + 20; if (tx + 220 > rect.width) tx = mx - 220 - 20; tooltip.style.left = tx + "px"; var ty = my + 20; if (ty + 150 > rect.height) ty = my - 150; tooltip.style.top = ty + "px";
        };
        chartSVG.onmouseleave = function () { cursorLine.style.display = "none"; tooltip.style.display = "none"; };
    }

    function refreshData(t1, t2, cb) {
        if (!overlay.parentNode) return;
        var now = t2 || Date.now();
        var from = t1 || (now - timeRange * 3600000);
        var pending = activeSeries.length;
        var results = [];

        if (timeWrap && timeWrap.childNodes) {
            timeWrap.childNodes.forEach(function (btn) { if (btn.update) btn.update(); });
        }

        if (pending === 0) {
            drawMultiChart([], from, now);
            if (cb) cb();
            return;
        }

        activeSeries.forEach(function (s, idx) {
            var sPath = s.addr;
            if (sPath.indexOf("s=") >= 0) sPath = sPath.slice(sPath.indexOf("s=") + 2);

            var cbHandler = function (series) {
                results[idx] = { name: s.name, color: s.color, data: series, type: s.type, disabled: s.disabled, equip: s.equip, site: s.site };
                pending--;
                if (pending === 0) {
                    drawMultiChart(results, from, now);
                    if (overlay._updateVolume) overlay._updateVolume(from, now);
                    if (overlay._updateAverages) overlay._updateAverages(from, now);
                    if (cb) cb();
                }
            };
            U.readHist(sPath, from, now, cbHandler);
        });
    }

    function updateSeriesUI() {
        seriesList.innerHTML = "";

        // Collect unique sites
        var siteNames = [];
        activeSeries.forEach(function (s) {
            var sn = s.site || "SITIO";
            if (siteNames.indexOf(sn) === -1) siteNames.push(sn);
        });
        siteNames.sort();

        var categories = [
            { label: "NIVEL 1: NIVELES Y QUÍMICA", types: ["tank", "chlorine"] },
            { label: "NIVEL 2: CAUDALÍMETROS", types: ["flow", "pressure"] },
            { label: "NIVEL 3: EQUIPOS DE BOMBEO", types: ["status_e", "status_m", "status_l"] }
        ];

        siteNames.forEach(function (site) {
            // Site Section Header
            var siteHeader = x("div");
            setS(siteHeader, {
                padding: "12px 10px 4px",
                background: "rgba(59, 130, 246, 0.08)",
                color: "#3b82f6",
                fontWeight: "900",
                fontSize: "11px",
                letterSpacing: "1px",
                borderLeft: "3px solid #3b82f6",
                marginTop: "16px",
                borderRadius: "0 4px 4px 0",
                textTransform: "uppercase"
            });
            siteHeader.textContent = site;
            seriesList.appendChild(siteHeader);

            categories.forEach(function (cat) {
                var filtered = activeSeries.filter(function (s) {
                    return (s.site || "SITIO") === site && cat.types.indexOf(s.type) >= 0;
                });
                if (filtered.length === 0) return;

                var catHead = x("div");
                setS(catHead, { fontSize: "9px", fontWeight: "900", color: "#475569", padding: "8px 0 4px 10px", letterSpacing: "0.05em" });
                catHead.textContent = cat.label.split(":")[1].trim();
                seriesList.appendChild(catHead);

                // --- GROUPING LOGIC (Specifically for Level 3 / Pumps) ---
                var groups = {};
                var order = [];
                filtered.forEach(function (s) {
                    // Clean name: Remove "Tanque ", "Carcamo ", "Cárcamo ", and leading digits
                    var cleaned = s.name.replace(/Tanque\s?|Carcamo\s?|Cárcamo\s?/gi, "").replace(/^[0-9]+:\s*/, "").trim();
                    s._dispName = cleaned;

                    // Grouping key for Pumps (e.g., "Bomba 1")
                    var gKey = cleaned;
                    if (cat.types.indexOf("status_e") >= 0) {
                        gKey = cleaned.split(" (")[0].replace(" - ENCENDIDO", "").replace(" - MAN/AUTO", "").replace(" - LOC/REM", "").trim();
                    }

                    if (!groups[gKey]) { groups[gKey] = []; order.push(gKey); }
                    groups[gKey].push(s);
                });

                order.forEach(function (gKey) {
                    var members = groups[gKey];
                    var isLevel3 = cat.types.indexOf("status_e") >= 0;

                    if (isLevel3 && members.length > 1) {
                        // Group Header (Toggles all members)
                        var gHeader = x("div");
                        var allOn = members.every(function (m) { return !m.disabled; });
                        setS(gHeader, {
                            background: "rgba(30, 41, 59, 0.5)", padding: "6px 12px", borderRadius: "6px 6px 0 0",
                            marginTop: "4px", marginLeft: "8px", display: "flex", justifyContent: "space-between", alignItems: "center",
                            cursor: "pointer", borderBottom: "1px solid rgba(255,255,255,0.05)"
                        });
                        var gTitle = x("div"); setS(gTitle, { fontSize: "10px", fontWeight: "900", color: "#94a3b8" }); gTitle.textContent = gKey.toUpperCase();
                        var gToggle = x("span"); gToggle.textContent = allOn ? "▼" : "▷"; setS(gToggle, { fontSize: "10px", color: "#64748b" });
                        gHeader.appendChild(gTitle); gHeader.appendChild(gToggle);

                        gHeader.onclick = function () {
                            var targetState = !allOn;
                            members.forEach(function (m) { m.disabled = !targetState; });
                            updateSeriesUI();
                            refreshData(inDe && inDe.value ? new Date(inDe.value + "T00:00:00").getTime() : null, inA && inA.value ? new Date(inA.value + "T23:59:59").getTime() : null);
                        };
                        seriesList.appendChild(gHeader);
                    }

                    members.forEach(function (s) {
                        var item = x("div");
                        var isOff = s.disabled;
                        var isMember = isLevel3 && members.length > 1;

                        setS(item, {
                            background: "#1e293b", padding: "8px 12px", borderRadius: isMember ? "0" : "6px",
                            marginBottom: isMember ? "0" : "4px", marginLeft: "8px",
                            borderBottom: isMember ? "1px solid rgba(255,255,255,0.03)" : "none",
                            display: "flex", justifyContent: "space-between", alignItems: "center",
                            cursor: "pointer", transition: "all 0.2s", opacity: isOff ? "0.4" : "1"
                        });
                        if (isMember && s === members[members.length - 1]) setS(item, { borderRadius: "0 0 6px 6px", marginBottom: "4px" });

                        var leftPart = x("div"); setS(leftPart, { display: "flex", alignItems: "center", gap: "8px" });
                        var icon = x("div");
                        var iconChar = (cat.label.indexOf("NIVEL 1") >= 0 ? "💧" : (cat.label.indexOf("NIVEL 2") >= 0 ? "📊" : "⚙️"));
                        setS(icon, { width: "16px", height: "16px", display: "flex", alignItems: "center", justifyContent: "center", fontSize: "10px", borderRadius: "3px", background: isOff ? "#475569" : s.color, color: "white" });
                        icon.textContent = iconChar;

                        var nameSpan = x("span");
                        var disp = s._dispName;
                        if (isMember) {
                            disp = disp.replace(gKey, "").replace(/[\-\(\)\s]+/g, " ").trim() || "GENERAL";
                        }
                        nameSpan.textContent = disp;
                        setS(nameSpan, { fontSize: "11px", fontWeight: "bold" });
                        leftPart.appendChild(icon); leftPart.appendChild(nameSpan);
                        item.appendChild(leftPart);

                        var toggleIcon = x("span"); toggleIcon.textContent = isOff ? "○" : "●";
                        setS(toggleIcon, { color: isOff ? "#64748b" : s.color, fontSize: "14px" });
                        item.appendChild(toggleIcon);

                        item.onclick = function (ev) {
                            ev.stopPropagation();
                            s.disabled = !s.disabled;
                            updateSeriesUI();
                            refreshData(inDe && inDe.value ? new Date(inDe.value + "T00:00:00").getTime() : null, inA && inA.value ? new Date(inA.value + "T23:59:59").getTime() : null);
                        };
                        seriesList.appendChild(item);
                    });
                });
            });
        });
    }

    btnLocal.onclick = function () {
        if (currentMode === "local") return;
        currentMode = "local";
        if (overlay._subs) { overlay._subs.forEach(function (id) { webMI.data.unsubscribe(id); }); overlay._subs = []; }

        if (overlay._tMain) overlay._tMain.textContent = "Dashboard de Sitio";
        if (overlay._tSub) overlay._tSub.textContent = getCleanSiteName(base.split(".").pop());

        if (overlay._pumpLbl) {
            overlay._pumpLbl.style.display = "block";
            overlay._pumpLbl.textContent = isAR ? "BOMBAS DEL CÁRCAMO" : "BOMBAS DEL TANQUE";
        }
        if (overlay._pumpList) overlay._pumpList.style.display = "block";
        if (overlay._legDiv) overlay._legDiv.style.display = "block";

        btnLocal.style.background = "#3b82f6"; btnLocal.style.color = "white";
        btnCirc.style.background = "transparent"; btnCirc.style.color = "#94a3b8";

        if (overlay._avgQLbl) overlay._avgQLbl.textContent = isAR ? "PROMEDIO DE CAUDAL DEL CÁRCAMO" : "PROMEDIO DE CAUDAL DEL TANQUE";
        if (overlay._tfLbl) overlay._tfLbl.textContent = "CAUDAL EN TIEMPO REAL";
        if (overlay._volLbl) overlay._volLbl.textContent = isAR ? "VOLUMEN DEL CÁRCAMO" : "VOLUMEN DEL TANQUE";
        if (overlay._avgPLbl) overlay._avgPLbl.textContent = isAR ? "PROMEDIO DE PRESIÓN DEL CÁRCAMO" : "PROMEDIO DE PRESIÓN DEL TANQUE";

        if (overlay._setProgress) overlay._setProgress(5);
        if (overlay._btnExport) {
            overlay._btnExport.disabled = true;
            overlay._btnExport.style.opacity = "0.4";
        }

        var siteName = getCleanSiteName(base.split(".").pop());
        activeSeries = [
            { name: siteName + " (Nivel)", addr: base + ".historic_level_percent", color: "#3b82f6", type: "tank", site: siteName },
            { name: "Cloro", addr: base + ".historic_ppm", color: "#f59e0b", type: "chlorine", site: siteName }
        ];

        // STEP 1: Discover Equipment
        updatePumps();
        U.discoverEquipment(base, function (data) {
            if (overlay._setProgress) overlay._setProgress(30);
            var colors = ["#10b981", "#06b6d4", "#8b5cf6", "#ec4899", "#f43f5e", "#fb923c", "#a855f7", "#22d3ee"];
            var cIdx = 0;
            var meterValues = {};
            var pressureValues = {};

            function updateTF() {
                var sumQ = 0, sumP = 0, countP = 0;
                var listQ = [], listP = [];
                for (var k in meterValues) {
                    var dsQ = activeSeries.filter(function (s) { return s.addr.indexOf(k) >= 0 && s.type === "flow"; })[0];
                    if (dsQ && dsQ.disabled) continue;
                    sumQ += meterValues[k];
                    listQ.push({ name: k.replace(/^[0-9]+:\s*/, "").replace(/_/g, " "), val: meterValues[k] });
                }
                for (var k in pressureValues) {
                    var dsP = activeSeries.filter(function (s) { return s.addr.indexOf(k) >= 0 && s.type === "pressure"; })[0];
                    if (dsP && dsP.disabled) continue;
                    sumP += pressureValues[k];
                    countP++;
                    listP.push({ name: k.replace(/^[0-9]+:\s*/, "").replace(/_/g, " "), val: pressureValues[k] });
                }
                if (tfVal) tfVal.firstChild.textContent = sumQ.toFixed(2);
                if (overlay._tpVal) overlay._tpVal.firstChild.textContent = (countP > 0 ? (sumP / countP) : 0).toFixed(2);

                if (overlay._realQList) {
                    overlay._realQList.innerHTML = "";
                    if (data.meters.length > 1) {
                        listQ.forEach(function (item) {
                            var row = x("div"); setS(row, { display: "flex", justifyContent: "space-between", fontSize: "11px", color: "#94a3b8", paddingBottom: "2px", borderBottom: "1px solid rgba(255,255,255,0.03)" });
                            var nSpan = x("span"); nSpan.textContent = item.name;
                            var vSpan = x("b"); vSpan.textContent = item.val.toFixed(2) + " l/s"; setS(vSpan, { color: "#f8fafc" });
                            row.appendChild(nSpan); row.appendChild(vSpan); overlay._realQList.appendChild(row);
                        });
                    }
                }
                if (overlay._realPList) {
                    overlay._realPList.innerHTML = "";
                    if (data.meters.length > 1) {
                        listP.forEach(function (item) {
                            var row = x("div"); setS(row, { display: "flex", justifyContent: "space-between", fontSize: "11px", color: "#64748b", paddingBottom: "2px", borderBottom: "1px solid rgba(255,255,255,0.03)" });
                            var nSpan = x("span"); nSpan.textContent = item.name;
                            var vSpan = x("b"); vSpan.textContent = item.val.toFixed(2) + " kg"; setS(vSpan, { color: "#f8fafc" });
                            row.appendChild(nSpan); row.appendChild(vSpan); overlay._realPList.appendChild(row);
                        });
                    }
                }
            }

            data.meters.forEach(function (m) {
                var mName = m.name.replace(/^[0-9]+:\s*/, "").replace(/_/g, " ");
                U.addSub(m.address + ".historic_flow", function (res) {
                    meterValues[m.name] = (res && res.value != null ? parseFloat(res.value) : 0);
                    updateTF();
                }, overlay._subs);
                activeSeries.push({ name: mName + " (Q)", addr: m.address + ".historic_flow", color: colors[cIdx % colors.length], type: "flow", site: siteName });
                cIdx++;

                if (!isAR) {
                    U.addSub(m.address + ".historic_pressure", function (res) {
                        pressureValues[m.name] = (res && res.value != null ? parseFloat(res.value) : 0);
                        updateTF();
                    }, overlay._subs);
                    activeSeries.push({ name: mName + " (P)", addr: m.address + ".historic_pressure", color: colors[cIdx % colors.length], type: "pressure", site: siteName });
                    cIdx++;
                }
            });

            data.pumps.forEach(function (p) {
                var sPath = p.address;
                if (sPath.indexOf("s=") >= 0) sPath = sPath.slice(sPath.indexOf("s=") + 2);
                var pCleanName = getCleanSiteName(p.name);
                activeSeries.push({ name: pCleanName + " (Marcha)", addr: sPath + ".Alarma_Estatus", color: "#22c55e", type: "status_e", equip: pCleanName, site: siteName });
                activeSeries.push({ name: pCleanName + " (Modo)", addr: sPath + ".Alarma_ManAuto", color: "#3b82f6", type: "status_m", equip: pCleanName, site: siteName });
                activeSeries.push({ name: pCleanName + " (Control)", addr: sPath + ".Alarma_Local", color: "#f97316", type: "status_l", equip: pCleanName, site: siteName });
            });

            // STEP 2: Render UI and Chart
            updateSeriesUI();
            refreshData(null, null, function () {
                if (overlay._setProgress) overlay._setProgress(70);

                // STEP 3: Right Panel Calculations
                var cachedMeters = data.meters.slice();

                function updateVolume(customFrom, customTo) {
                    if (!volVal) return;
                    var now = customTo || Date.now(), from = customFrom || (now - timeRange * 3600000);
                    var totalDelta = 0, meterDeltas = [], pending = cachedMeters.length;
                    if (pending === 0) return;
                    cachedMeters.forEach(function (m, idx) {
                        U.readHist(m.address + ".current_total_volume", from, now, function (series) {
                            pending--;
                            var ds = activeSeries.filter(function (s) { return s.addr.indexOf(m.address) >= 0 && s.type === "flow"; })[0];
                            var delta = 0;
                            if (ds && !ds.disabled && series && series.length >= 2) {
                                var first = series[0], last = series[series.length - 1];
                                var isFirstOlder = first.t < last.t;
                                var oldVal = isFirstOlder ? first.v : last.v, newVal = isFirstOlder ? last.v : first.v;
                                delta = newVal - oldVal; if (delta > 0) totalDelta += delta;
                            }
                            meterDeltas[idx] = { name: m.name.replace(/^[0-9]+:\s*/, "").replace(/_/g, " "), val: delta > 0 ? delta : 0 };
                            if (pending === 0) {
                                if (overlay._volList) {
                                    overlay._volList.innerHTML = "";
                                    if (data.meters.length > 1) {
                                        meterDeltas.forEach(function (md) {
                                            var row = x("div"); setS(row, { display: "flex", justifyContent: "space-between", fontSize: "11px", color: "#94a3b8", paddingBottom: "2px", borderBottom: "1px solid rgba(255,255,255,0.03)" });
                                            var nSpan = x("span"); nSpan.textContent = md.name;
                                            var vSpan = x("b"); vSpan.textContent = md.val.toFixed(2) + " m³"; setS(vSpan, { color: "#f8fafc" });
                                            row.appendChild(nSpan); row.appendChild(vSpan); overlay._volList.appendChild(row);
                                        });
                                    }
                                }
                                volVal.firstChild.textContent = totalDelta.toFixed(2);
                                checkAllDone();
                            }
                        });
                    });
                }
                overlay._updateVolume = updateVolume;

                function updateAverages(customFrom, customTo) {
                    if (!overlay._avgQVal || !overlay._avgQList || !overlay._avgPVal || !overlay._avgPList) return;
                    var now = customTo || Date.now(), from = customFrom || (now - timeRange * 3600000);
                    var meterAvgsQ = [], meterAvgsP = [], totalAvgQ = 0, sumAvgP = 0, countP = 0, pending = cachedMeters.length * 2;
                    if (pending === 0) return;
                    cachedMeters.forEach(function (m, idx) {
                        U.readHist(m.address + ".historic_flow", from, now, function (series) {
                            pending--;
                            var ds = activeSeries.filter(function (s) { return s.addr.indexOf(m.address) >= 0 && s.type === "flow"; })[0];
                            var avg = 0; if (ds && !ds.disabled && series && series.length > 0) { var sum = 0; series.forEach(function (p) { sum += p.v; }); avg = sum / series.length; }
                            meterAvgsQ[idx] = { name: m.name.replace(/^[0-9]+:\s*/, "").replace(/_/g, " "), val: avg }; totalAvgQ += avg;
                            if (pending === 0) render();
                        });
                        U.readHist(m.address + ".historic_pressure", from, now, function (series) {
                            pending--;
                            var avg = 0; if (series && series.length > 0) { var sum = 0; series.forEach(function (p) { sum += p.v; }); avg = sum / series.length; }
                            meterAvgsP[idx] = { name: m.name.replace(/^[0-9]+:\s*/, "").replace(/_/g, " "), val: avg }; sumAvgP += avg; countP++;
                            if (pending === 0) render();
                        });
                    });
                    function render() {
                        overlay._avgQList.innerHTML = ""; overlay._avgPList.innerHTML = "";
                        if (data.meters.length > 1) {
                            meterAvgsQ.forEach(function (ma) {
                                var row = x("div"); setS(row, { display: "flex", justifyContent: "space-between", fontSize: "11px", color: "#64748b", paddingBottom: "2px", borderBottom: "1px solid rgba(255,255,255,0.03)" });
                                var nSpan = x("span"); nSpan.textContent = ma.name;
                                var vSpan = x("span"); vSpan.textContent = "Prom: " + ma.val.toFixed(2) + " l/s"; setS(vSpan, { color: "#94a3b8" });
                                row.appendChild(nSpan); row.appendChild(vSpan); overlay._avgQList.appendChild(row);
                            });
                            meterAvgsP.forEach(function (ma) {
                                var row = x("div"); setS(row, { display: "flex", justifyContent: "space-between", fontSize: "11px", color: "#64748b", paddingBottom: "2px", borderBottom: "1px solid rgba(255,255,255,0.03)" });
                                var nSpan = x("span"); nSpan.textContent = ma.name;
                                var vSpan = x("span"); vSpan.textContent = "Prom: " + ma.val.toFixed(2) + " kg"; setS(vSpan, { color: "#94a3b8" });
                                row.appendChild(nSpan); row.appendChild(vSpan); overlay._avgPList.appendChild(row);
                            });
                        }
                        overlay._avgQVal.firstChild.textContent = totalAvgQ.toFixed(2);
                        overlay._avgPVal.firstChild.textContent = (countP > 0 ? (sumAvgP / countP) : 0).toFixed(2);
                        checkAllDone();
                    }
                }
                overlay._updateAverages = updateAverages;

                var doneCount = 0;
                function checkAllDone() {
                    doneCount++;
                    if (doneCount >= 2) {
                        if (overlay._setProgress) overlay._setProgress(100);
                        saveConfig();
                    }
                }

                updateVolume();
                updateAverages();
            });
        });
    };

    btnCirc.onclick = function () {
        if (currentMode === "circuit") return;
        currentMode = "circuit";
        if (overlay._subs) { overlay._subs.forEach(function (id) { webMI.data.unsubscribe(id); }); overlay._subs = []; }

        if (overlay._tMain) overlay._tMain.textContent = isAR ? "Dashboard de Cuenca" : "Dashboard de Circuito";
        if (overlay._tSub) overlay._tSub.textContent = getCleanGroupName(base);

        if (overlay._pumpLbl) overlay._pumpLbl.style.display = "none";
        if (overlay._pumpList) overlay._pumpList.style.display = "none";
        if (overlay._legDiv) overlay._legDiv.style.display = "none";
        tpDiv.style.display = "none";
        avgPDiv.style.display = "none";

        btnCirc.style.background = "#3b82f6"; btnCirc.style.color = "white";
        btnLocal.style.background = "transparent"; btnLocal.style.color = "#94a3b8";

        if (overlay._avgQLbl) overlay._avgQLbl.textContent = isAR ? "PROMEDIO DE CAUDAL DE LA CUENCA" : "PROMEDIO DE CAUDAL DEL CIRCUITO";
        if (overlay._tfLbl) overlay._tfLbl.textContent = isAR ? "CAUDAL EN TIEMPO REAL DE LA CUENCA" : "CAUDAL EN TIEMPO REAL DEL CIRCUITO";
        if (overlay._volLbl) overlay._volLbl.textContent = isAR ? "VOLUMEN BOMBEADO TOTAL DE LA CUENCA" : "VOLUMEN BOMBEADO TOTAL DEL CIRCUITO";

        if (overlay._setProgress) overlay._setProgress(5);
        if (overlay._btnExport) {
            overlay._btnExport.disabled = true;
            overlay._btnExport.style.opacity = "0.4";
        }

        var groupName = getCleanGroupName(base);
        var siteName = getCleanSiteName(base.split(".").pop());
        activeSeries = [{ name: groupName + " (Nivel)", addr: base + ".historic_level_percent", color: "#3b82f6", type: "tank", site: siteName }];

        // STEP 1: Discovery Global
        HeaderTopo.fetchConfig(base + ".topoNode", function (topo) {
            if (overlay._setProgress) overlay._setProgress(30);

            var colors = ["#f59e0b", "#10b981", "#8b5cf6", "#ec4899", "#06b6d4", "#22d3ee", "#fb923c", "#a855f7"];
            var cIdx = 0;
            var allMeters = [];
            var nodes = (topo && topo.nodes) ? topo.nodes : [];

            nodes.forEach(function (n) {
                if (n.base && n.base !== base && (n.base.indexOf("Tanque") >= 0 || n.base.indexOf("Carcamo") >= 0)) {
                    var cleanName = getCleanSiteName(n.id);
                    activeSeries.push({ name: cleanName + " (Nivel)", addr: n.base + ".historic_level_percent", color: colors[cIdx % colors.length], type: "tank", site: cleanName });
                    cIdx++;
                }
            });

            var pendingDiscovery = nodes.length;
            if (pendingDiscovery === 0) { finalizeDiscovery(); return; }

            nodes.forEach(function (n) {
                if (!n.base) { pendingDiscovery--; if (pendingDiscovery === 0) finalizeDiscovery(); return; }
                U.discoverEquipment(n.base, function (data) {
                    pendingDiscovery--;
                    data.meters.forEach(function (m) {
                        m.siteName = getCleanSiteName(n.id);
                        allMeters.push(m);
                    });
                    if (pendingDiscovery === 0) finalizeDiscovery();
                });
            });

            function finalizeDiscovery() {
                var meterValues = {};
                // Note: pressureValues removal requested to minimize requests in Circuit Mode

                function updateTFGlobal() {
                    var sumQ = 0;
                    var listQ = [];
                    for (var k in meterValues) {
                        var ds = activeSeries.filter(function (s) { return s.addr === k + ".historic_flow"; })[0];
                        if (ds && ds.disabled) continue;
                        sumQ += meterValues[k].val;
                        listQ.push({ site: meterValues[k].site, name: meterValues[k].name, val: meterValues[k].val });
                    }
                    if (tfVal) tfVal.firstChild.textContent = sumQ.toFixed(2);

                    if (overlay._realQList) {
                        overlay._realQList.innerHTML = "";
                        listQ.sort(function (a, b) { return (a.site || "").localeCompare(b.site || ""); }).forEach(function (item) {
                            var row = x("div"); setS(row, { display: "flex", justifyContent: "space-between", fontSize: "11px", color: "#94a3b8", paddingBottom: "2px", borderBottom: "1px solid rgba(255,255,255,0.03)" });
                            var nSpan = x("span"); nSpan.innerHTML = '<small style="color:#64748b">[' + (item.site || "---") + ']</small> ' + item.name;
                            var vSpan = x("b"); vSpan.textContent = item.val.toFixed(2) + " l/s"; setS(vSpan, { color: "#f8fafc" });
                            row.appendChild(nSpan); row.appendChild(vSpan); overlay._realQList.appendChild(row);
                        });
                    }
                }

                allMeters.forEach(function (m) {
                    var mCleanName = m.name.replace(/^[0-9]+:\s*/, "").replace(/_/g, " ");

                    U.addSub(m.address + ".historic_flow", function (res) {
                        meterValues[m.address] = { site: m.siteName, name: mCleanName, val: (res && res.value != null ? parseFloat(res.value) : 0) };
                        updateTFGlobal();
                    }, overlay._subs);

                    activeSeries.push({ name: mCleanName + " (Q)", addr: m.address + ".historic_flow", color: colors[cIdx % colors.length], type: "flow", site: m.siteName });
                    cIdx++;

                    if (!isAR) {
                        activeSeries.push({ name: mCleanName + " (P)", addr: m.address + ".historic_pressure", color: colors[cIdx % colors.length], type: "pressure", site: m.siteName });
                        cIdx++;
                    }
                });

                // STEP 2: Render UI and Chart
                updateSeriesUI();
                refreshData(null, null, function () {
                    if (overlay._setProgress) overlay._setProgress(70);

                    // STEP 3: Right Panel Calculations
                    var cachedMeters = allMeters.slice();

                    function updateVolumeGlobal(customFrom, customTo) {
                        if (!volVal) return;
                        var now = customTo || Date.now(), from = customFrom || (now - timeRange * 3600000);
                        var totalDelta = 0, meterDeltas = [], pending = cachedMeters.length;
                        if (pending === 0) return;
                        cachedMeters.forEach(function (m, idx) {
                            U.readHist(m.address + ".current_total_volume", from, now, function (series) {
                                pending--;
                                var delta = 0;
                                if (series && series.length >= 2) {
                                    var first = series[0], last = series[series.length - 1];
                                    var isFirstOlder = first.t < last.t;
                                    var oldVal = isFirstOlder ? first.v : last.v, newVal = isFirstOlder ? last.v : first.v;
                                    delta = newVal - oldVal; if (delta > 0) totalDelta += delta;
                                }
                                meterDeltas[idx] = { site: m.siteName, name: m.name.replace(/^[0-9]+:\s*/, "").replace(/_/g, " "), val: delta > 0 ? delta : 0 };
                                if (pending === 0) {
                                    if (overlay._volList) {
                                        overlay._volList.innerHTML = "";
                                        meterDeltas.forEach(function (md) {
                                            var row = x("div"); setS(row, { display: "flex", justifyContent: "space-between", fontSize: "11px", color: "#94a3b8", paddingBottom: "2px", borderBottom: "1px solid rgba(255,255,255,0.03)" });
                                            var nSpan = x("span"); nSpan.innerHTML = '<small style="color:#64748b">[' + md.site + ']</small> ' + md.name;
                                            var vSpan = x("b"); vSpan.textContent = md.val.toFixed(2) + " m³"; setS(vSpan, { color: "#f8fafc" });
                                            row.appendChild(nSpan); row.appendChild(vSpan); overlay._volList.appendChild(row);
                                        });
                                    }
                                    volVal.firstChild.textContent = totalDelta.toFixed(2);
                                    checkGlobalDone();
                                }
                            });
                        });
                    }
                    overlay._updateVolume = updateVolumeGlobal;

                    function updateAveragesGlobal(customFrom, customTo) {
                        if (!overlay._avgQVal || !overlay._avgPVal) return;
                        var now = customTo || Date.now(), from = customFrom || (now - timeRange * 3600000);
                        var meterAvgsQ = [], meterAvgsP = [], totalAvgQ = 0, sumAvgP = 0, countP = 0, pending = cachedMeters.length * 2;
                        if (pending === 0) return;
                        cachedMeters.forEach(function (m, idx) {
                            U.readHist(m.address + ".historic_flow", from, now, function (series) {
                                pending--;
                                var avg = 0; if (series && series.length > 0) { var sum = 0; series.forEach(function (p) { sum += p.v; }); avg = sum / series.length; }
                                meterAvgsQ[idx] = { site: m.siteName, name: m.name.replace(/^[0-9]+:\s*/, "").replace(/_/g, " "), val: avg }; totalAvgQ += avg;
                                if (pending === 0) render();
                            });
                            U.readHist(m.address + ".historic_pressure", from, now, function (series) {
                                pending--;
                                var avg = 0; if (series && series.length > 0) { var sum = 0; series.forEach(function (p) { sum += p.v; }); avg = sum / series.length; }
                                meterAvgsP[idx] = { site: m.siteName, name: m.name.replace(/^[0-9]+:\s*/, "").replace(/_/g, " "), val: avg }; sumAvgP += avg; countP++;
                                if (pending === 0) render();
                            });
                        });

                        function render() {
                            if (overlay._avgQList) {
                                overlay._avgQList.innerHTML = "";
                                meterAvgsQ.forEach(function (ma) {
                                    var row = x("div"); setS(row, { display: "flex", justifyContent: "space-between", fontSize: "11px", color: "#64748b", paddingBottom: "2px", borderBottom: "1px solid rgba(255,255,255,0.03)" });
                                    var nSpan = x("span"); nSpan.innerHTML = '<small style="color:#64748b">[' + ma.site + ']</small> ' + ma.name;
                                    var vSpan = x("span"); vSpan.textContent = "Prom: " + ma.val.toFixed(2) + " l/s"; setS(vSpan, { color: "#94a3b8" });
                                    row.appendChild(nSpan); row.appendChild(vSpan); overlay._avgQList.appendChild(row);
                                });
                            }
                            if (overlay._avgPList) {
                                overlay._avgPList.innerHTML = "";
                                meterAvgsP.forEach(function (ma) {
                                    var row = x("div"); setS(row, { display: "flex", justifyContent: "space-between", fontSize: "11px", color: "#64748b", paddingBottom: "2px", borderBottom: "1px solid rgba(255,255,255,0.03)" });
                                    var nSpan = x("span"); nSpan.innerHTML = '<small style="color:#64748b">[' + ma.site + ']</small> ' + ma.name;
                                    var vSpan = x("span"); vSpan.textContent = "Prom: " + ma.val.toFixed(2) + " kg"; setS(vSpan, { color: "#94a3b8" });
                                    row.appendChild(nSpan); row.appendChild(vSpan); overlay._avgPList.appendChild(row);
                                });
                            }
                            overlay._avgQVal.firstChild.textContent = totalAvgQ.toFixed(2);
                            overlay._avgPVal.firstChild.textContent = (countP > 0 ? (sumAvgP / countP) : 0).toFixed(2);
                            checkGlobalDone();
                        }
                    }
                    overlay._updateAverages = updateAveragesGlobal;

                    var gDoneCount = 0;
                    function checkGlobalDone() {
                        gDoneCount++;
                        if (gDoneCount >= 2) {
                            if (overlay._setProgress) overlay._setProgress(100);
                            saveConfig();
                        }
                    }

                    updateVolumeGlobal();
                    updateAveragesGlobal();
                });
            }
        });
    };

    overlay._subs = [];
    overlay._onClose = function () {
        overlay._subs.forEach(function (id) { webMI.data.unsubscribe(id); });
    };

    loadConfig(function () {
        if (currentMode === "circuit") {
            btnCirc.click();
        } else {
            // Default to local/site if null or local
            if (currentMode !== "local") currentMode = null; // Reset to allow first click
            btnLocal.click();
        }
    });

    /* 
    var refreshInt = setInterval(function () {
        if (currentMode !== "circuit") refreshData();
    }, 30000);
    */
};
